import React, { useState, useEffect, useRef } from 'react';
import { ChatMessage } from '../types';

interface ChatInterfaceProps {
  chatHistory: ChatMessage[];
  onSendMessage: (message: string) => void;
  loading: boolean;
  error: string | null;
  onBackToForm: () => void;
  onClearChat: () => void;
  suggestedQuestions: string[];
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  chatHistory,
  onSendMessage,
  loading,
  error,
  onBackToForm,
  onClearChat,
  suggestedQuestions,
}) => {
  const [currentInput, setCurrentInput] = useState<string>('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [chatHistory]);

  const handleSend = () => {
    if (currentInput.trim()) {
      onSendMessage(currentInput);
      setCurrentInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-[75vh] md:h-[80vh] glass rounded-3xl overflow-hidden shadow-2xl border border-white/10">
      {/* Header */}
      <div className="px-6 py-4 bg-white/5 border-b border-white/10 flex justify-between items-center">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-purple-500 to-blue-500 flex items-center justify-center shadow-lg">
            <span className="text-xl">✨</span>
          </div>
          <div>
            <h2 className="text-lg font-bold text-white leading-tight">Cosmic Oracle</h2>
            <div className="flex items-center text-xs text-green-400">
              <span className="w-2 h-2 rounded-full bg-green-400 mr-2 animate-pulse"></span>
              Live Insights
            </div>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={onClearChat}
            className="px-3 py-1.5 text-xs font-semibold text-gray-300 hover:text-white hover:bg-white/10 rounded-lg transition-all"
          >
            Reset
          </button>
          <button
            onClick={onBackToForm}
            className="px-4 py-1.5 text-xs font-bold bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all border border-white/10"
          >
            ← Chart
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Main Chat Area */}
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Question Feed / Suggestions */}
          {chatHistory.length <= 1 && suggestedQuestions.length > 0 && (
            <div className="p-4 bg-white/5 border-b border-white/5 overflow-x-auto whitespace-nowrap scrollbar-hide">
              <p className="text-[10px] uppercase tracking-wider text-gray-400 mb-2 px-1">Suggested Inquiries</p>
              <div className="flex space-x-2">
                {suggestedQuestions.map((q, i) => (
                  <button
                    key={i}
                    onClick={() => onSendMessage(q)}
                    className="px-3 py-1.5 text-xs bg-white/5 hover:bg-blue-500/20 border border-white/10 rounded-full text-blue-200 transition-all"
                  >
                    {q}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
            {chatHistory.map((msg, index) => (
              <div
                key={index}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
              >
                <div
                  className={`max-w-[85%] px-5 py-3 rounded-2xl shadow-lg border ${
                    msg.role === 'user'
                      ? 'bg-blue-600/20 border-blue-500/30 text-blue-50'
                      : 'bg-white/5 border-white/10 text-gray-200'
                  }`}
                >
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                </div>
              </div>
            ))}
            {loading && (
              <div className="flex justify-start">
                <div className="bg-white/5 border border-white/10 px-5 py-3 rounded-2xl flex items-center space-x-2">
                  <div className="flex space-x-1">
                    <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                  <span className="text-xs text-blue-300/70 font-medium">Stargazing...</span>
                </div>
              </div>
            )}
            {error && (
              <div className="mx-auto max-w-sm text-center p-3 bg-red-500/10 border border-red-500/30 text-red-400 text-xs rounded-xl">
                {error}
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Area */}
          <div className="p-4 bg-white/5 border-t border-white/10">
            <div className="relative flex items-center">
              <input
                type="text"
                value={currentInput}
                onChange={(e) => setCurrentInput(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Ask about your destiny, finance, or planets..."
                className="w-full bg-black/30 border border-white/10 rounded-2xl py-3.5 pl-5 pr-14 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all"
                disabled={loading}
              />
              <button
                onClick={handleSend}
                disabled={loading || !currentInput.trim()}
                className="absolute right-2 p-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl shadow-lg transition-all disabled:opacity-50"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, FinancialGoal, ApiResponse, ChatMessage } from './types';
import { getCombinedReading, initializeChatSession, sendChatMessage } from './services/geminiService';
import InputField from './components/InputField';
import CheckboxField from './components/CheckboxField';
import ChatInterface from './components/ChatInterface';
import { saveStateToLocalStorage, loadStateFromLocalStorage } from './utils/storage';
import { Chat } from '@google/genai';

const APP_STATE_KEY = 'cosmicCompassAppState';

interface AppState {
  birthDetails: BirthDetails;
  readingOptions: ReadingOptions;
  advancedReadingOptions: AdvancedReadingOptions;
  lifeEvents: LifeEvent[];
  outputLanguage: string;
  exSpouseDetails?: SpouseDetails;
  financialGoal: FinancialGoal;
  enableGoogleSearch: boolean;
  chatHistory: ChatMessage[];
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() =>
    loadStateFromLocalStorage<AppState>(APP_STATE_KEY, {
      birthDetails: {
        name: 'Harshkumar Panubhai Patel',
        dob: '1995-01-17',
        tob: '15:58',
        pob: 'Vadodara, Gujarat, India',
        rashi: 'Cancer',
      },
      readingOptions: {
        astrology: true,
        numerology: true,
        rashifal: true,
        jyotish: true,
        dailyHoroscope: true,
        weeklyHoroscope: true,
      },
      advancedReadingOptions: {
        culturalContext: 'Vedic',
        includeScientificPerspective: true,
      },
      lifeEvents: [
        { description: 'Moved to Germany', date: '2024-11-06' },
        { description: 'Divorce', date: '2025-10-17' },
      ],
      outputLanguage: 'Gujarati',
      exSpouseDetails: { name: '', dob: '' },
      financialGoal: { targetAmount: null, currentSavings: null, timeframeMonths: null },
      enableGoogleSearch: false,
      chatHistory: [],
    })
  );

  const { birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, financialGoal, enableGoogleSearch, chatHistory } = appState;

  const [newEventDescription, setNewEventDescription] = useState<string>('');
  const [newEventDate, setNewEventDate] = useState<string>('');
  const [reading, setReading] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [groundingSources, setGroundingSources] = useState<ApiResponse['groundingSources']>([]);
  const [isChatMode, setIsChatMode] = useState<boolean>(false);
  const [currentChatSession, setCurrentChatSession] = useState<Chat | undefined>(undefined);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);

  useEffect(() => {
    saveStateToLocalStorage(APP_STATE_KEY, appState);
  }, [appState]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    updateAppState({ birthDetails: { ...birthDetails, [name]: value } });
  };

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, checked } = e.target;
    updateAppState({ readingOptions: { ...readingOptions, [name]: checked } });
  };

  const handleAdvancedInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    updateAppState({ advancedReadingOptions: { ...advancedReadingOptions, [name]: value } });
  };

  const handleExSpouseInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { id, value } = e.target;
    updateAppState({
      exSpouseDetails: { ...exSpouseDetails, [id === 'exSpouseName' ? 'name' : 'dob']: value } as SpouseDetails,
    });
  };

  const handleFinancialGoalInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { id, value } = e.target;
    updateAppState({
      financialGoal: { ...financialGoal, [id]: value === '' ? null : Number(value) },
    });
  };

  const handleAddLifeEvent = () => {
    if (newEventDescription.trim() && newEventDate) {
      updateAppState({ lifeEvents: [...lifeEvents, { description: newEventDescription.trim(), date: newEventDate }] });
      setNewEventDescription('');
      setNewEventDate('');
    }
  };

  const handleRemoveLifeEvent = (index: number) => {
    updateAppState({ lifeEvents: lifeEvents.filter((_, i) => i !== index) });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, financialGoal, enableGoogleSearch);
      setReading(result.reading);
      setGroundingSources(result.groundingSources || []);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const initializeChat = useCallback(async () => {
    setChatLoading(true);
    setChatError(null);
    try {
      const chat = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, financialGoal, enableGoogleSearch);
      setCurrentChatSession(chat);
      setAppState(prev => prev.chatHistory.length === 0 ? {
        ...prev,
        chatHistory: [{ role: 'model', text: `Namaste ${birthDetails.name}. I have analyzed your birth chart (Rashi: ${birthDetails.rashi}) and life events. I am ready to guide you on your destiny, career, and financial path. What shall we explore first?` }]
      } : prev);
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, financialGoal, enableGoogleSearch]);

  const handleSendMessage = async (message: string) => {
    if (!currentChatSession) return;
    setAppState(prev => ({ ...prev, chatHistory: [...prev.chatHistory, { role: 'user', text: message }, { role: 'model', text: '' }] }));
    setChatLoading(true);
    let fullText = '';
    try {
      const stream = sendChatMessage(currentChatSession, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  };

  const suggestedQuestions = useMemo(() => {
    const qs = [
      `How does my ${birthDetails.rashi} Rashi affect my current luck?`,
      "What are the best financial remedies for my situation?",
      "Can you analyze my career prospects in the next 6 months?",
    ];
    if (financialGoal.targetAmount) qs.push(`Will I reach my goal of ${financialGoal.targetAmount} INR?`);
    if (lifeEvents.some(e => e.description.toLowerCase().includes('divorce'))) qs.push("What do the planets say about my remarriage timing?");
    return qs;
  }, [birthDetails.rashi, financialGoal.targetAmount, lifeEvents]);

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      {/* Navigation Tabs */}
      <div className="flex justify-center mb-10">
        <div className="glass p-1.5 rounded-2xl flex space-x-2">
          <button
            onClick={() => setIsChatMode(false)}
            className={`px-8 py-2.5 rounded-xl font-bold transition-all ${!isChatMode ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
          >
            Insights Center
          </button>
          <button
            onClick={() => {
              setIsChatMode(true);
              if (!currentChatSession) initializeChat();
            }}
            className={`px-8 py-2.5 rounded-xl font-bold transition-all ${isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
          >
            Cosmic Chat
          </button>
        </div>
      </div>

      {!isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          {/* Left Column: Form Details */}
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center">
                <span className="mr-3 text-blue-400">✵</span> Birth Profile
              </h2>
              <div className="space-y-4">
                <InputField label="Name" id="name" type="text" value={birthDetails.name} onChange={handleInputChange} required />
                <div className="grid grid-cols-2 gap-4">
                  <InputField label="DOB" id="dob" type="date" value={birthDetails.dob} onChange={handleInputChange} required />
                  <InputField label="TOB" id="tob" type="time" value={birthDetails.tob} onChange={handleInputChange} required />
                </div>
                <InputField label="Place" id="pob" type="text" value={birthDetails.pob} onChange={handleInputChange} placeholder="City, Country" required />
                <InputField label="Rashi" id="rashi" type="text" value={birthDetails.rashi || ''} onChange={handleInputChange} placeholder="Moon Sign" required />
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center">
                <span className="mr-3 text-purple-400">⟁</span> Analysis Focus
              </h2>
              <div className="grid grid-cols-2 gap-2">
                {Object.keys(readingOptions).map((key) => (
                  <CheckboxField
                    key={key}
                    label={key.charAt(0).toUpperCase() + key.slice(1).replace(/([A-Z])/g, ' $1')}
                    id={key}
                    checked={(readingOptions as any)[key]}
                    onChange={handleCheckboxChange}
                  />
                ))}
              </div>
            </section>
          </div>

          {/* Middle Column: Life Events & Goals */}
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5 bg-blue-500/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center">
                <span className="mr-3 text-green-400">⌛</span> Timeline
              </h2>
              <div className="space-y-3 mb-6 max-h-48 overflow-y-auto custom-scrollbar">
                {lifeEvents.map((event, i) => (
                  <div key={i} className="glass-dark p-3 rounded-xl flex justify-between items-center text-xs">
                    <div>
                      <div className="font-semibold text-white">{event.description}</div>
                      <div className="text-gray-400">{event.date}</div>
                    </div>
                    <button onClick={() => handleRemoveLifeEvent(i)} className="text-red-400 hover:text-red-300">✕</button>
                  </div>
                ))}
              </div>
              <div className="space-y-3">
                <input
                  className="w-full bg-black/20 border border-white/10 rounded-xl p-2.5 text-sm text-white focus:outline-none focus:ring-1 focus:ring-blue-500"
                  placeholder="Event (e.g., Job Loss)"
                  value={newEventDescription}
                  onChange={e => setNewEventDescription(e.target.value)}
                />
                <input
                  type="date"
                  className="w-full bg-black/20 border border-white/10 rounded-xl p-2.5 text-sm text-white focus:outline-none focus:ring-1 focus:ring-blue-500"
                  value={newEventDate}
                  onChange={e => setNewEventDate(e.target.value)}
                />
                <button onClick={handleAddLifeEvent} className="w-full bg-white/10 hover:bg-white/20 text-white font-bold py-2 rounded-xl transition-all border border-white/5">
                  Add Event to Timeline
                </button>
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center">
                <span className="mr-3 text-yellow-400">◈</span> Financial Target
              </h2>
              <div className="space-y-4">
                <InputField label="Target (INR)" id="targetAmount" type="number" value={financialGoal.targetAmount?.toString() || ''} onChange={handleFinancialGoalInputChange} />
                <InputField label="Time (Months)" id="timeframeMonths" type="number" value={financialGoal.timeframeMonths?.toString() || ''} onChange={handleFinancialGoalInputChange} />
              </div>
            </section>
          </div>

          {/* Right Column: Generation & Output */}
          <div className="lg:col-span-4 flex flex-col h-full">
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-5 rounded-3xl shadow-2xl transition-all disabled:opacity-50 mb-6 flex items-center justify-center space-x-3 text-lg"
            >
              {loading ? (
                <>
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                  <span>Reading the Stars...</span>
                </>
              ) : (
                <>
                  <span>✨</span>
                  <span>Generate Full Reading</span>
                </>
              )}
            </button>

            {reading && (
              <div className="glass rounded-3xl p-6 border border-white/10 flex-1 overflow-y-auto max-h-[600px] animate-in fade-in zoom-in-95 duration-500">
                <h3 className="font-serif text-xl text-blue-300 mb-4 border-b border-white/10 pb-2">Celestial Wisdom</h3>
                <div className="text-gray-200 text-sm leading-relaxed space-y-4 whitespace-pre-wrap">
                  {reading}
                </div>
                {groundingSources.length > 0 && (
                  <div className="mt-8 pt-4 border-t border-white/10">
                    <p className="text-[10px] text-gray-400 uppercase tracking-widest mb-3">Grounding Sources</p>
                    <div className="space-y-2">
                      {groundingSources.map((s, i) => (
                        <a key={i} href={s.web?.uri} target="_blank" className="block text-xs text-blue-400 hover:underline truncate">
                          🔗 {s.web?.title || s.web?.uri}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
            {!reading && !loading && (
              <div className="glass rounded-3xl p-8 border border-white/5 flex-1 flex flex-col items-center justify-center text-center text-gray-500">
                <div className="text-5xl mb-4">🔮</div>
                <p className="text-sm">Complete your profile and click generate to reveal your cosmic insights.</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto">
          <ChatInterface
            chatHistory={chatHistory}
            onSendMessage={handleSendMessage}
            loading={chatLoading}
            error={chatError}
            onBackToForm={() => setIsChatMode(false)}
            onClearChat={() => {
              updateAppState({ chatHistory: [] });
              setCurrentChatSession(undefined);
              initializeChat();
            }}
            suggestedQuestions={suggestedQuestions}
          />
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';

interface InputFieldProps {
  label: string;
  id: string;
  type: React.HTMLInputTypeAttribute;
  value: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  placeholder?: string;
  required?: boolean;
  min?: string;
}

const InputField: React.FC<InputFieldProps> = ({
  label,
  id,
  type,
  value,
  onChange,
  placeholder,
  required = false,
  min,
}) => {
  return (
    <div className="mb-1">
      <label htmlFor={id} className="block text-[10px] uppercase tracking-widest text-gray-400 font-bold mb-1.5 px-1">
        {label} {required && <span className="text-blue-400">*</span>}
      </label>
      <input
        type={type}
        id={id}
        name={id}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        required={required}
        min={min}
        className="w-full bg-black/20 border border-white/10 rounded-xl py-2.5 px-4 text-sm text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500/50 transition-all"
      />
    </div>
  );
};

export default InputField;

import React from 'react';

interface CheckboxFieldProps {
  label: string;
  id: string;
  checked: boolean;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
}

const CheckboxField: React.FC<CheckboxFieldProps> = ({ label, id, checked, onChange }) => {
  return (
    <label className="flex items-center p-2.5 rounded-xl border border-white/5 hover:bg-white/5 transition-all cursor-pointer">
      <div className="relative flex items-center">
        <input
          type="checkbox"
          id={id}
          name={id}
          checked={checked}
          onChange={onChange}
          className="peer appearance-none h-4 w-4 bg-black/20 border border-white/20 rounded focus:ring-0 focus:ring-offset-0 transition-all"
        />
        <svg
          className="absolute w-4 h-4 text-blue-500 hidden peer-checked:block pointer-events-none"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth="4"
        >
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
        </svg>
      </div>
      <span className={`ml-3 text-xs transition-all ${checked ? 'text-white font-semibold' : 'text-gray-400'}`}>
        {label}
      </span>
    </label>
  );
};

export default CheckboxField;

export interface BirthDetails {
  name: string;
  dob: string; // YYYY-MM-DD
  tob: string; // HH:MM
  pob: string; // Place of Birth (city, country)
  rashi?: string; 
}

export interface ReadingOptions {
  astrology: boolean;
  numerology: boolean;
  rashifal: boolean;
  jyotish: boolean;
  dailyHoroscope: boolean;
  palmistry: boolean;
  lalKitab: boolean;
  vasthu: boolean;
  faceReading: boolean;
}

export interface AdvancedReadingOptions {
  culturalContext: string; 
  includeScientificPerspective: boolean;
}

export interface LifeEvent {
  description: string;
  date: string; // YYYY-MM-DD
}

export interface SpouseDetails {
  name: string;
  dob: string; 
}

export interface ApiResponse {
  reading: string;
  groundingSources?: { web?: { uri: string; title?: string } }[];
}

export interface GeminiError {
  message: string;
}

export interface ChatMessage {
