import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, ApiResponse } from "../types";

function buildAstrologyPrompt(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  isChatContext: boolean = false
): string {
  const today = new Date();
  const dateString = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  let prompt = isChatContext 
    ? `You are an Omni-Esoteric Master. You possess deep knowledge of Astrology, Numerology, Jyotish, Palmistry, Lal Kitab, Vasthu Shastra, and Face Reading. Provide detailed, mystical, and accurate readings.`
    : `Generate a holistic esoteric reading based on birth data, ancient sciences, and life events.`;

  if (outputLanguage === 'Gujarati') {
    prompt += ` The entire response MUST be in the Gujarati language using authentic spiritual terminology.`;
  } else {
    prompt += ` The response should be in ${outputLanguage}.`;
  }

  prompt += `\n\nUser Profile:
- Name: ${birthDetails.name}
- Born: ${birthDetails.dob} at ${birthDetails.tob} in ${birthDetails.pob}
${birthDetails.rashi ? `- Rashi: ${birthDetails.rashi}` : ''}`;

  if (exSpouseDetails?.name) {
    prompt += `\n\nRelationship Context: Ex-spouse ${exSpouseDetails.name} (DOB: ${exSpouseDetails.dob}). Use this for karmic relationship analysis.`;
  }

  prompt += `\n\nRequested Disciplines:`;
  if (options.dailyHoroscope) prompt += `\n- Daily Guidance for ${dateString}`;
  if (options.astrology) prompt += `\n- Western Astrology (Signs & Aspects)`;
  if (options.numerology) prompt += `\n- Numerology (Life Path, Destiny Number)`;
  if (options.jyotish) prompt += `\n- Vedic Jyotish (Dashas, Nakshatras)`;
  if (options.palmistry) prompt += `\n- Palmistry (Inferred traits from planetary strengths)`;
  if (options.lalKitab) prompt += `\n- Lal Kitab (House-based remedies and "Blind Planets")`;
  if (options.vasthu) prompt += `\n- Vasthu Shastra (Home energy and spatial alignment)`;
  if (options.faceReading) prompt += `\n- Face Reading (Physiognomy based on elemental signatures)`;

  if (lifeEvents.length > 0) {
    prompt += `\n\nLife Timeline:`;
    lifeEvents.forEach(e => prompt += `\n- ${e.description} (${e.date})`);
  }

  prompt += `\n\nAnalysis Requirements:
1. Synthesize all active disciplines into a unified life path.
2. Provide specific Lal Kitab remedies (Upay).
3. Suggest Vasthu corrections for their current living space.
4. Analyze the "Why" behind past events using Dashas.
5. Predict future windows for career, health, and personal growth.
6. If Palmistry is enabled, describe what their "Heart Line" and "Life Line" likely indicate given their birth chart.`;

  return prompt;
}

export async function getCombinedReading(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  enableGoogleSearch: boolean = false,
): Promise<ApiResponse> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, false);

  const modelConfig: any = {
    temperature: 0.8,
    maxOutputTokens: 32768,
    thinkingConfig: { thinkingBudget: 20000 },
  };

  if (enableGoogleSearch) modelConfig.tools = [{ googleSearch: {} }];

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: modelConfig,
    });
    return { reading: response.text || "Connection to stars lost.", groundingSources: response.candidates?.[0]?.groundingMetadata?.groundingChunks };
  } catch (error: any) {
    return { reading: `Cosmic Error: ${error.message}` };
  }
}

export async function initializeChatSession(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  enableGoogleSearch: boolean = false,
): Promise<Chat> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const systemInstruction = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, true);

  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction,
      temperature: 0.9,
    },
  });
}

export async function* sendChatMessage(chatSession: Chat, message: string): AsyncGenerator<string, void, unknown> {
  const responseStream = await chatSession.sendMessageStream({ message });
  for await (const chunk of responseStream) {
    const c = chunk as GenerateContentResponse;
    if (c.text) yield c.text;
  }
}

import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, ApiResponse, ChatMessage } from './types';
import { getCombinedReading, initializeChatSession, sendChatMessage } from './services/geminiService';
import InputField from './components/InputField';
import CheckboxField from './components/CheckboxField';
import ChatInterface from './components/ChatInterface';
import { saveStateToLocalStorage, loadStateFromLocalStorage } from './utils/storage';
import { Chat } from '@google/genai';

const APP_STATE_KEY = 'cosmicCompassAppState_v2';

interface AppState {
  birthDetails: BirthDetails;
  readingOptions: ReadingOptions;
  advancedReadingOptions: AdvancedReadingOptions;
  lifeEvents: LifeEvent[];
  outputLanguage: string;
  exSpouseDetails?: SpouseDetails;
  enableGoogleSearch: boolean;
  chatHistory: ChatMessage[];
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() =>
    loadStateFromLocalStorage<AppState>(APP_STATE_KEY, {
      birthDetails: {
        name: 'Harshkumar Panubhai Patel',
        dob: '1995-01-17',
        tob: '15:58',
        pob: 'Vadodara, Gujarat, India',
        rashi: 'Cancer',
      },
      readingOptions: {
        astrology: true,
        numerology: true,
        rashifal: true,
        jyotish: true,
        dailyHoroscope: true,
        palmistry: true,
        lalKitab: true,
        vasthu: false,
        faceReading: false,
      },
      advancedReadingOptions: {
        culturalContext: 'Vedic',
        includeScientificPerspective: true,
      },
      lifeEvents: [
        { description: 'Moved to Germany', date: '2024-11-06' },
        { description: 'Divorce', date: '2025-10-17' },
      ],
      outputLanguage: 'Gujarati',
      exSpouseDetails: { name: '', dob: '' },
      enableGoogleSearch: false,
      chatHistory: [],
    })
  );

  const { birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, chatHistory } = appState;

  const [newEventDescription, setNewEventDescription] = useState<string>('');
  const [newEventDate, setNewEventDate] = useState<string>('');
  const [reading, setReading] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [groundingSources, setGroundingSources] = useState<ApiResponse['groundingSources']>([]);
  const [isChatMode, setIsChatMode] = useState<boolean>(false);
  const [currentChatSession, setCurrentChatSession] = useState<Chat | undefined>(undefined);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);

  useEffect(() => {
    saveStateToLocalStorage(APP_STATE_KEY, appState);
  }, [appState]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    updateAppState({ birthDetails: { ...birthDetails, [name]: value } });
  };

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, checked } = e.target;
    updateAppState({ readingOptions: { ...readingOptions, [name]: checked } });
  };

  const handleAddLifeEvent = () => {
    if (newEventDescription.trim() && newEventDate) {
      updateAppState({ lifeEvents: [...lifeEvents, { description: newEventDescription.trim(), date: newEventDate }] });
      setNewEventDescription('');
      setNewEventDate('');
    }
  };

  const handleRemoveLifeEvent = (index: number) => {
    updateAppState({ lifeEvents: lifeEvents.filter((_, i) => i !== index) });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch);
      setReading(result.reading);
      setGroundingSources(result.groundingSources || []);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const initializeChat = useCallback(async () => {
    setChatLoading(true);
    setChatError(null);
    try {
      const chat = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch);
      setCurrentChatSession(chat);
      if (appState.chatHistory.length === 0) {
        setAppState(prev => ({
          ...prev,
          chatHistory: [{ role: 'model', text: `Namaste ${birthDetails.name}. I have aligned the stars, analyzed your palm lines, and decoded your Lal Kitab chart. How can I guide you today?` }]
        }));
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, appState.chatHistory.length]);

  const handleSendMessage = async (message: string) => {
    if (!currentChatSession) return;
    setAppState(prev => ({ ...prev, chatHistory: [...prev.chatHistory, { role: 'user', text: message }, { role: 'model', text: '' }] }));
    setChatLoading(true);
    let fullText = '';
    try {
      const stream = sendChatMessage(currentChatSession, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  };

  const suggestedQuestions = useMemo(() => {
    const qs = [
      "What are the best Lal Kitab remedies for my current Dasha?",
      "Can you analyze the Vasthu of my North-facing home?",
      "What does my Sun Line say about my fame potential?",
      "How does my Rashi affect my relationship path?",
    ];
    return qs;
  }, []);

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <div className="flex justify-center mb-10">
        <div className="glass p-1.5 rounded-2xl flex space-x-2">
          <button onClick={() => setIsChatMode(false)} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${!isChatMode ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Insights Center</button>
          <button onClick={() => { setIsChatMode(true); if (!currentChatSession) initializeChat(); }} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Cosmic Chat</button>
        </div>
      </div>

      {!isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-blue-400">✵</span> Birth Profile</h2>
              <div className="space-y-4">
                <InputField label="Name" id="name" type="text" value={birthDetails.name} onChange={handleInputChange} required />
                <div className="grid grid-cols-2 gap-4">
                  <InputField label="DOB" id="dob" type="date" value={birthDetails.dob} onChange={handleInputChange} required />
                  <InputField label="TOB" id="tob" type="time" value={birthDetails.tob} onChange={handleInputChange} required />
                </div>
                <InputField label="Place" id="pob" type="text" value={birthDetails.pob} onChange={handleInputChange} placeholder="City, Country" required />
                <InputField label="Rashi" id="rashi" type="text" value={birthDetails.rashi || ''} onChange={handleInputChange} placeholder="Moon Sign" required />
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-purple-400">📜</span> Ancient Sciences</h2>
              <div className="grid grid-cols-2 gap-2">
                {Object.keys(readingOptions).map((key) => (
                  <CheckboxField
                    key={key}
                    label={key.charAt(0).toUpperCase() + key.slice(1).replace(/([A-Z])/g, ' $1')}
                    id={key}
                    checked={(readingOptions as any)[key]}
                    onChange={handleCheckboxChange}
                  />
                ))}
              </div>
            </section>
          </div>

          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5 bg-blue-500/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-green-400">⌛</span> Life Timeline</h2>
              <div className="space-y-3 mb-6 max-h-64 overflow-y-auto custom-scrollbar">
                {lifeEvents.map((event, i) => (
                  <div key={i} className="glass-dark p-3 rounded-xl flex justify-between items-center text-xs">
                    <div>
                      <div className="font-semibold text-white">{event.description}</div>
                      <div className="text-gray-400">{event.date}</div>
                    </div>
                    <button onClick={() => handleRemoveLifeEvent(i)} className="text-red-400 hover:text-red-300">✕</button>
                  </div>
                ))}
              </div>
              <div className="space-y-3">
                <input className="w-full bg-black/20 border border-white/10 rounded-xl p-2.5 text-sm text-white focus:outline-none focus:ring-1 focus:ring-blue-500" placeholder="New Event..." value={newEventDescription} onChange={e => setNewEventDescription(e.target.value)} />
                <input type="date" className="w-full bg-black/20 border border-white/10 rounded-xl p-2.5 text-sm text-white focus:outline-none focus:ring-1 focus:ring-blue-500" value={newEventDate} onChange={e => setNewEventDate(e.target.value)} />
                <button onClick={handleAddLifeEvent} className="w-full bg-white/10 hover:bg-white/20 text-white font-bold py-2 rounded-xl transition-all border border-white/5">Add to Life Path</button>
              </div>
            </section>
          </div>

          <div className="lg:col-span-4 flex flex-col h-full">
            <button onClick={handleSubmit} disabled={loading} className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-5 rounded-3xl shadow-2xl transition-all disabled:opacity-50 mb-6 flex items-center justify-center space-x-3 text-lg">
              {loading ? <><div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div><span>Decrypting Destiny...</span></> : <><span>✨</span><span>Generate Omni Reading</span></>}
            </button>

            {reading && (
              <div className="glass rounded-3xl p-6 border border-white/10 flex-1 overflow-y-auto max-h-[700px] animate-in fade-in zoom-in-95 duration-500">
                <h3 className="font-serif text-xl text-blue-300 mb-4 border-b border-white/10 pb-2">Ancient Wisdom</h3>
                <div className="text-gray-200 text-sm leading-relaxed space-y-4 whitespace-pre-wrap">{reading}</div>
                {groundingSources && groundingSources.length > 0 && (
                  <div className="mt-8 pt-4 border-t border-white/10">
                    <p className="text-[10px] text-gray-400 uppercase tracking-widest mb-3">Grounding Sources</p>
                    <div className="space-y-2">
                      {groundingSources.map((s, i) => (
                        <a key={i} href={s.web?.uri} target="_blank" className="block text-xs text-blue-400 hover:underline truncate">🔗 {s.web?.title || s.web?.uri}</a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
            {!reading && !loading && (
              <div className="glass rounded-3xl p-8 border border-white/5 flex-1 flex flex-col items-center justify-center text-center text-gray-500">
                <div className="text-5xl mb-4">🧿</div>
                <p className="text-sm italic">"The stars only guide those who seek."</p>
                <p className="text-xs mt-4">Select your sciences and generate your path.</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto">
          <ChatInterface chatHistory={chatHistory} onSendMessage={handleSendMessage} loading={chatLoading} error={chatError} onBackToForm={() => setIsChatMode(false)} onClearChat={() => { updateAppState({ chatHistory: [] }); setCurrentChatSession(undefined); initializeChat(); }} suggestedQuestions={suggestedQuestions} />
        </div>
      )}
    </div>
  );
};

