import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, ApiResponse } from "../types";

function buildAstrologyPrompt(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  isChatContext: boolean = false
): string {
  const today = new Date();
  const dateString = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  let prompt = isChatContext 
    ? `You are an Omni-Esoteric Master. You possess deep knowledge of Astrology, Numerology, Jyotish, Palmistry, Lal Kitab, Vasthu Shastra, and Face Reading. 
    IMPORTANT: You have access to user's Left Hand, Right Hand, and Face images.
    - Compare Left (Prarabdha/Past) and Right (Purushartha/Future) hands for a complete Palmistry reading.
    - Analyze the Face for character and luck (Physiognomy).
    - Provide specific Lal Kitab remedies and Vasthu advice.`
    : `Generate a holistic esoteric reading based on birth data and ancient sciences. Focus on synthesis.`;

  if (outputLanguage === 'Gujarati') {
    prompt += ` Respond EXCLUSIVELY in Gujarati using high-quality spiritual vocabulary.`;
  } else {
    prompt += ` Respond in ${outputLanguage}.`;
  }

  prompt += `\n\nUser Profile:
- Name: ${birthDetails.name}
- Born: ${birthDetails.dob} at ${birthDetails.tob} in ${birthDetails.pob}
${birthDetails.rashi ? `- Rashi: ${birthDetails.rashi}` : ''}`;

  if (lifeEvents.length > 0) {
    prompt += `\n\nSignificant Events:`;
    lifeEvents.forEach(e => prompt += `\n- ${e.description} on ${e.date}`);
  }

  prompt += `\n\nAnalyze these specific disciplines: ${Object.keys(options).filter(k => (options as any)[k]).join(', ')}.`;

  return prompt;
}

export async function getCombinedReading(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  enableGoogleSearch: boolean = false,
  visuals?: { leftHand?: string; rightHand?: string; face?: string }
): Promise<ApiResponse> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, false);

  const parts: any[] = [{ text: prompt }];

  if (visuals) {
    if (visuals.leftHand) parts.push({ inlineData: { mimeType: 'image/jpeg', data: visuals.leftHand.split(',')[1] } });
    if (visuals.rightHand) parts.push({ inlineData: { mimeType: 'image/jpeg', data: visuals.rightHand.split(',')[1] } });
    if (visuals.face) parts.push({ inlineData: { mimeType: 'image/jpeg', data: visuals.face.split(',')[1] } });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts },
      config: {
        temperature: 0.8,
        thinkingConfig: { thinkingBudget: 20000 },
      },
    });
    return { reading: response.text || "Connection failed." };
  } catch (error: any) {
    return { reading: `Error: ${error.message}` };
  }
}

export async function initializeChatSession(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
): Promise<Chat> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const systemInstruction = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, true);

  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction,
      temperature: 0.9,
    },
  });
}

export async function* sendChatMessage(
  chatSession: Chat, 
  message: string, 
  visuals: { leftHand?: string; rightHand?: string; face?: string }
): AsyncGenerator<string, void, unknown> {
  const parts: any[] = [{ text: message }];

  if (visuals.leftHand) parts.push({ inlineData: { mimeType: 'image/jpeg', data: visuals.leftHand.split(',')[1] } });
  if (visuals.rightHand) parts.push({ inlineData: { mimeType: 'image/jpeg', data: visuals.rightHand.split(',')[1] } });
  if (visuals.face) parts.push({ inlineData: { mimeType: 'image/jpeg', data: visuals.face.split(',')[1] } });

  const responseStream = await chatSession.sendMessageStream({ message: { parts } });
  for await (const chunk of responseStream) {
    const c = chunk as GenerateContentResponse;
    if (c.text) yield c.text;
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { ChatMessage } from '../types';

interface ChatInterfaceProps {
  chatHistory: ChatMessage[];
  onSendMessage: (message: string) => void;
  loading: boolean;
  error: string | null;
  onBackToForm: () => void;
  onClearChat: () => void;
  suggestedQuestions: string[];
  visuals: { leftHand?: string; rightHand?: string; face?: string };
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  chatHistory,
  onSendMessage,
  loading,
  error,
  onBackToForm,
  onClearChat,
  suggestedQuestions,
  visuals
}) => {
  const [currentInput, setCurrentInput] = useState<string>('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(scrollToBottom, [chatHistory]);

  const handleSend = () => {
    if (currentInput.trim()) {
      onSendMessage(currentInput);
      setCurrentInput('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const hasAnyVisual = visuals.leftHand || visuals.rightHand || visuals.face;

  return (
    <div className="flex flex-col h-[75vh] md:h-[80vh] glass rounded-3xl overflow-hidden shadow-2xl border border-white/10">
      {/* Header */}
      <div className="px-6 py-4 bg-white/5 border-b border-white/10 flex justify-between items-center">
