            {visuals.rightHand && <img src={visuals.rightHand} className="inline-block h-10 w-10 rounded-full ring-2 ring-blue-500 object-cover" alt="Right" />}
            {!hasAnyVisual && <div className="h-10 w-10 rounded-full bg-white/10 flex items-center justify-center ring-2 ring-white/20">✨</div>}
          </div>
          <div>
            <h2 className="text-lg font-bold text-white leading-tight">Cosmic Oracle</h2>
            <div className="text-[10px] text-blue-400 font-bold uppercase tracking-widest">
              {hasAnyVisual ? 'Visual Analysis Active' : 'Reading Profile...'}
            </div>
          </div>
        </div>
        <div className="flex space-x-2">
          <button onClick={onClearChat} className="px-3 py-1.5 text-xs text-gray-400 hover:text-white transition-colors">Reset</button>
          <button onClick={onBackToForm} className="px-4 py-1.5 text-xs font-bold bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all border border-white/10">Back</button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-black/10">
        {chatHistory.map((msg, index) => (
          <div key={index} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] px-5 py-3 rounded-2xl shadow-lg border ${msg.role === 'user' ? 'bg-blue-600/20 border-blue-500/30 text-blue-50' : 'bg-white/5 border-white/10 text-gray-200'}`}>
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-white/5 border border-white/10 px-5 py-3 rounded-2xl animate-pulse">
              <div className="flex space-x-1">
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Suggested Questions */}
      <div className="p-3 bg-white/5 border-t border-white/5 overflow-x-auto whitespace-nowrap flex space-x-2 scrollbar-hide">
        {suggestedQuestions.map((q, i) => (
          <button key={i} onClick={() => onSendMessage(q)} className="px-3 py-1.5 text-xs bg-white/5 hover:bg-white/10 border border-white/10 rounded-full text-blue-200 transition-all">
            {q}
          </button>
        ))}
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white/5 border-t border-white/10">
        <div className="relative flex items-center">
          <input
            type="text"
            value={currentInput}
            onChange={(e) => setCurrentInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Ask about your palm lines or face reading..."
            className="w-full bg-black/40 border border-white/10 rounded-2xl py-3.5 pl-5 pr-14 text-sm text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50"
            disabled={loading}
          />
          <button
            onClick={handleSend}
            disabled={loading || !currentInput.trim()}
            className="absolute right-2 p-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl shadow-lg transition-all"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

