    leftHand?: string;
    rightHand?: string;
    face?: string;
  };
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    // 1. Try to load from the stable key
    const saved = loadStateFromLocalStorage<AppState | null>(APP_STATE_KEY, null);
    if (saved && saved.lifeEvents && saved.lifeEvents.length > 0) return saved;

    // 2. Migration: Check old keys if new key is empty or missing
    for (const oldKey of OLD_KEYS) {
      const oldData = loadStateFromLocalStorage<AppState | null>(oldKey, null);
      if (oldData && oldData.lifeEvents && oldData.lifeEvents.length > 0) {
        console.log(`Migrated ${oldData.lifeEvents.length} events from ${oldKey}`);
        return oldData;
      }
    }

    // 3. Fallback to default
    return {
      birthDetails: {
        name: 'Harshkumar Panubhai Patel',
        dob: '1995-01-17',
        tob: '15:58',
        pob: 'Vadodara, India',
        rashi: 'Cancer',
      },
      readingOptions: {
        astrology: true,
        numerology: true,
        rashifal: true,
        jyotish: true,
        dailyHoroscope: true,
        palmistry: true,
        lalKitab: true,
        vasthu: true,
        faceReading: true,
      },
      advancedReadingOptions: {
        culturalContext: 'Vedic',
        includeScientificPerspective: true,
      },
      lifeEvents: [], 
      outputLanguage: 'Gujarati',
      enableGoogleSearch: false,
      chatHistory: [],
      visuals: {}
    };
  });

  const { birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, enableGoogleSearch, chatHistory, visuals } = appState;

  const [reading, setReading] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [isChatMode, setIsChatMode] = useState<boolean>(false);
  const [currentChatSession, setCurrentChatSession] = useState<Chat | undefined>(undefined);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);

  const [newEventDesc, setNewEventDesc] = useState('');
  const [newEventDate, setNewEventDate] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadSlot, setActiveUploadSlot] = useState<'leftHand' | 'rightHand' | 'face' | null>(null);

  useEffect(() => {
    saveStateToLocalStorage(APP_STATE_KEY, appState);
  }, [appState]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    updateAppState({ birthDetails: { ...birthDetails, [name]: value } });
  };

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, checked } = e.target;
    updateAppState({ readingOptions: { ...readingOptions, [name]: checked } });
  };

  const handleFileUpload = (slot: 'leftHand' | 'rightHand' | 'face') => {
    setActiveUploadSlot(slot);
    fileInputRef.current?.click();
  };

  const onFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeUploadSlot) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateAppState({ visuals: { ...visuals, [activeUploadSlot]: reader.result as string } });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddLifeEvent = () => {
    if (newEventDesc.trim() && newEventDate) {
      updateAppState({ lifeEvents: [...lifeEvents, { description: newEventDesc, date: newEventDate }] });
      setNewEventDesc('');
      setNewEventDate('');
    }
  };

  const handleRemoveLifeEvent = (index: number) => {
    updateAppState({ lifeEvents: lifeEvents.filter((_, i) => i !== index) });
  };

  const handleSubmitOmni = async () => {
    setLoading(true);
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, undefined, enableGoogleSearch, visuals);
      setReading(result.reading);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const startChat = useCallback(async () => {
    setIsChatMode(true);
    setChatLoading(true);
    try {
      const chat = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage);
      setCurrentChatSession(chat);
      if (appState.chatHistory.length === 0) {
        updateAppState({
          chatHistory: [{ role: 'model', text: `Pranam ${birthDetails.name}. My visual sensors are active. I have synced your profile with all ${lifeEvents.length} recorded life events. How shall we dive deeper into your destiny?` }]
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, appState.chatHistory.length]);

  const handleSendMessage = async (message: string) => {
    if (!currentChatSession) return;
    updateAppState({ chatHistory: [...chatHistory, { role: 'user', text: message }, { role: 'model', text: '' }] });
    setChatLoading(true);
    let fullText = '';
    try {
      const stream = sendChatMessage(currentChatSession, message, visuals);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  };

  const suggestedQuestions = useMemo(() => [
    "Explain my Left Hand's Life Line vs Right Hand.",
    "Analyze my past events using my birth chart.",
    "Give me Lal Kitab remedies for health.",
    "Check Vasthu for my entrance direction."
  ], [lifeEvents]);

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={onFileChange} />

      <div className="flex justify-center mb-10">
        <div className="glass p-1.5 rounded-2xl flex space-x-2">
          <button onClick={() => setIsChatMode(false)} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${!isChatMode ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Insights Center</button>
          <button onClick={startChat} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Cosmic Chat</button>
        </div>
      </div>

      {!isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-blue-400">✵</span> Birth Profile</h2>
              <div className="space-y-4">
                <InputField label="Name" id="name" type="text" value={birthDetails.name} onChange={handleInputChange} required />
                <div className="grid grid-cols-2 gap-4">
                  <InputField label="DOB" id="dob" type="date" value={birthDetails.dob} onChange={handleInputChange} required />
                  <InputField label="TOB" id="tob" type="time" value={birthDetails.tob} onChange={handleInputChange} required />
                </div>
                <InputField label="Place" id="pob" type="text" value={birthDetails.pob} onChange={handleInputChange} placeholder="City, Country" required />
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-purple-400">🧿</span> Visual Profile</h2>
              <div className="grid grid-cols-3 gap-3">
                {(['face', 'leftHand', 'rightHand'] as const).map(slot => (
                  <button key={slot} onClick={() => handleFileUpload(slot)} className="relative group rounded-xl overflow-hidden aspect-square border-2 border-dashed border-white/10 hover:border-purple-500/50 transition-all bg-black/20">
                    {visuals[slot] ? (
                      <img src={visuals[slot]} className="w-full h-full object-cover" alt={slot} />
                    ) : (
                      <div className="flex flex-col items-center justify-center h-full p-2">
                        <span className="text-xl mb-1">{slot === 'face' ? '👤' : '✋'}</span>
                        <span className="text-[8px] uppercase font-bold text-gray-500">{slot.replace(/([A-Z])/g, ' $1')}</span>
                      </div>
                    )}
                    <div className="absolute inset-0 bg-purple-600/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <span className="text-xs font-bold text-white">Change</span>
                    </div>
                  </button>
                ))}
              </div>
            </section>
          </div>

          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-yellow-400">📜</span> Ancient Sciences</h2>
              <div className="grid grid-cols-2 gap-2">
                {Object.keys(readingOptions).map((key) => (
                  <CheckboxField
                    key={key}
                    label={key.charAt(0).toUpperCase() + key.slice(1).replace(/([A-Z])/g, ' $1')}
                    id={key}
                    checked={(readingOptions as any)[key]}
                    onChange={handleCheckboxChange}
                  />
                ))}
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5 bg-blue-500/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-green-400">⌛</span> Life Timeline</h2>
              <div className="space-y-3 mb-6 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                {lifeEvents.map((event, i) => (
                  <div key={i} className="glass-dark p-3 rounded-xl flex justify-between items-center text-xs animate-in fade-in slide-in-from-left-2 duration-300">
                    <div className="flex-1 mr-4">
                      <div className="font-semibold text-white truncate">{event.description}</div>
                      <div className="text-gray-400 text-[10px]">{event.date}</div>
                    </div>
                    <button onClick={() => handleRemoveLifeEvent(i)} className="text-red-400 hover:text-red-300 p-1.5 hover:bg-white/5 rounded-lg transition-colors">✕</button>
                  </div>
                ))}
                {lifeEvents.length === 0 && <p className="text-xs text-gray-500 italic text-center py-10">Your life story starts here. Add events below.</p>}
              </div>
              <div className="space-y-2 pt-2 border-t border-white/10">
                <input className="w-full bg-black/30 border border-white/10 rounded-xl px-3 py-2.5 text-xs text-white placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-blue-500" placeholder="e.g. Major career promotion" value={newEventDesc} onChange={e => setNewEventDesc(e.target.value)} />
                <input type="date" className="w-full bg-black/30 border border-white/10 rounded-xl px-3 py-2.5 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500" value={newEventDate} onChange={e => setNewEventDate(e.target.value)} />
                <button onClick={handleAddLifeEvent} className="w-full bg-blue-600/20 hover:bg-blue-600/40 text-blue-200 text-xs font-bold py-2.5 rounded-xl border border-blue-500/20 transition-all">Add History Event</button>
              </div>
            </section>
          </div>

          <div className="lg:col-span-4 flex flex-col h-full">
            <button onClick={handleSubmitOmni} disabled={loading} className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-5 rounded-3xl shadow-2xl transition-all disabled:opacity-50 mb-6 flex items-center justify-center space-x-3 text-lg">
              {loading ? <><div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div><span>Analyzing Destiny...</span></> : <><span>✨</span><span>Generate Omni Reading</span></>}
            </button>

            {reading && (
              <div className="flex flex-col flex-1">
                <div className="glass rounded-3xl p-6 border border-white/10 flex-1 overflow-y-auto max-h-[500px] mb-4 custom-scrollbar">
                  <h3 className="font-serif text-xl text-blue-300 mb-4 border-b border-white/10 pb-2">Celestial Wisdom</h3>
                  <div className="text-gray-200 text-sm leading-relaxed space-y-4 whitespace-pre-wrap">{reading}</div>
                </div>
                <button onClick={startChat} className="w-full bg-white/10 hover:bg-white/20 text-blue-400 font-bold py-4 rounded-2xl transition-all border border-blue-400/20 shadow-xl group">
                  Dive Deeper with Cosmic Chat <span className="inline-block transition-transform group-hover:translate-x-1">→</span>
                </button>
              </div>
            )}
            {!reading && !loading && (
              <div className="glass rounded-3xl p-8 border border-white/5 flex-1 flex flex-col items-center justify-center text-center text-gray-500">
                <div className="text-5xl mb-4 opacity-30">🧿</div>
                <p className="text-sm italic">"The oracle awaits your full profile."</p>
                <p className="text-[10px] mt-4 uppercase tracking-widest text-blue-400/40">{lifeEvents.length} Events Synced</p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto">
          <ChatInterface 
            chatHistory={chatHistory} 
            onSendMessage={handleSendMessage} 
            loading={chatLoading} 
            error={chatError} 
            onBackToForm={() => setIsChatMode(false)} 
            onClearChat={() => { updateAppState({ chatHistory: [] }); setCurrentChatSession(undefined); startChat(); }} 
            suggestedQuestions={suggestedQuestions}
            visuals={visuals}
          />
        </div>
      )}
    </div>
  );
};

