              </div>
              <div className="space-y-3 pt-3 border-t border-white/10">
                <input className="w-full bg-black/20 border border-white/10 rounded-xl p-2.5 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500" placeholder="Event (e.g. Career Shift)" value={newEventDescription} onChange={e => setNewEventDescription(e.target.value)} />
                <input type="date" className="w-full bg-black/20 border border-white/10 rounded-xl p-2.5 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500" value={newEventDate} onChange={e => setNewEventDate(e.target.value)} />
                <button onClick={handleAddLifeEvent} className="w-full bg-white/10 hover:bg-white/20 text-white text-xs font-bold py-2.5 rounded-xl transition-all border border-white/5">Add to Life Path</button>
