  birthDetails: BirthDetails;
  readingOptions: ReadingOptions;
  advancedReadingOptions: AdvancedReadingOptions;
  lifeEvents: LifeEvent[];
  outputLanguage: string;
  exSpouseDetails?: SpouseDetails;
  enableGoogleSearch: boolean;
  chatHistory: ChatMessage[];
  visuals: Visuals;
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    // 1. Try loading the current stable key
    const currentData = loadStateFromLocalStorage<AppState | null>(CURRENT_STATE_KEY, null);
    if (currentData && currentData.lifeEvents && currentData.lifeEvents.length > 0) {
      return currentData;
    }

    // 2. Migration: Scan all previous storage locations to recover the 10+ events
    for (const oldKey of OLD_KEYS) {
      const oldData = loadStateFromLocalStorage<any | null>(oldKey, null);
      if (oldData && oldData.lifeEvents && oldData.lifeEvents.length > 0) {
        console.log(`Recovered ${oldData.lifeEvents.length} events from legacy storage: ${oldKey}`);
        return {
          ...oldData,
          visuals: oldData.visuals || {} 
        } as AppState;
      }
    }

    // 3. Hardcoded Fallback (Initial State): These are restored here so you never start with an empty list
    return {
      birthDetails: {
        name: 'Harshkumar Panubhai Patel',
        dob: '1995-01-17',
        tob: '15:58',
        pob: 'Vadodara, Gujarat, India',
        rashi: 'Cancer',
      },
      readingOptions: {
