          ...prev,
          chatHistory: [{ role: 'model', text: `Namaste ${birthDetails.name}. My visual sensors are synchronized. I have loaded your profile with ${Object.keys(visuals).length} visual inputs and all ${lifeEvents.length} life milestones. How shall we dive deeper today?` }]
        }));
