// All historical keys to scan for lost data
const LEGACY_KEYS = [
  'cosmic_compass_final_stable_v6',
  'cosmicCompassAppState_v5_final',
  'cosmicCompassAppState_v4', 
  'cosmicCompassAppState_v3', 
  'cosmicCompassAppState_v2', 
  'cosmicCompassAppState_v1', 
  'cosmicCompassAppState_final', 
  'cosmicCompassAppState_stable'
];

