    let recoveredEvents: LifeEvent[] = [];
    let recoveredVisuals: Visuals = {};
    let recoveredBirth: BirthDetails | null = null;
    let recoveredChat: ChatMessage[] = [];

    const seenEventKeys = new Set<string>();
    const seenChatKeys = new Set<string>();

    const addEvents = (events: any[]) => {
      if (!Array.isArray(events)) return;
      events.forEach(e => {
        const uniqueKey = `${e.description || ''}-${e.date || ''}`.trim().toLowerCase();
        if (uniqueKey !== '-' && uniqueKey !== '' && !seenEventKeys.has(uniqueKey)) {
          seenEventKeys.add(uniqueKey);
          recoveredEvents.push(e);
        }
      });
    };

    const addChat = (history: any[]) => {
      if (!Array.isArray(history)) return;
      history.forEach(msg => {
        const uniqueKey = `${msg.role}-${msg.text}`.trim();
        if (uniqueKey && !seenChatKeys.has(uniqueKey)) {
          seenChatKeys.add(uniqueKey);
          recoveredChat.push(msg);
        }
      });
    };

    // DEEP RECOVERY: Scan every known legacy key for data
    LEGACY_KEYS.forEach(key => {
      const data = loadStateFromLocalStorage<any>(key, null);
      if (data) {
        if (data.lifeEvents) addEvents(data.lifeEvents);
        if (data.chatHistory) addChat(data.chatHistory);
        if (!recoveredBirth && data.birthDetails) recoveredBirth = data.birthDetails;
        if (Object.keys(recoveredVisuals).length === 0 && data.visuals) recoveredVisuals = data.visuals;
      }
    });

    const defaultEvents: LifeEvent[] = [
      { description: 'Moved to Germany', date: '2024-11-06' },
      { description: 'Divorce Process / Life Shift', date: '2025-10-17' },
    ];

    if (recoveredEvents.length === 0) recoveredEvents = defaultEvents;

    return {
      birthDetails: recoveredBirth || {
        name: 'Harshkumar Panubhai Patel',
        dob: '1995-01-17',
        tob: '15:58',
        pob: 'Vadodara, Gujarat, India',
        rashi: 'Cancer',
      },
      readingOptions: {
        astrology: true,
        numerology: true,
        rashifal: true,
        jyotish: true,
        dailyHoroscope: true,
        palmistry: true,
        lalKitab: true,
        vasthu: true,
        faceReading: true,
      },
