  };

  const handleFileUpload = (slot: keyof Visuals) => {
    setActiveUploadSlot(slot);
    fileInputRef.current?.click();
  };

  const compressImage = (base64Str: string, maxWidth = 500, maxHeight = 500): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxWidth) { height *= maxWidth / width; width = maxWidth; }
        } else {
          if (height > maxHeight) { width *= maxHeight / height; height = maxHeight; }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.5));
      };
    });
  };

  const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeUploadSlot) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string);
        updateAppState({ visuals: { ...visuals, [activeUploadSlot]: compressed } });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddLifeEvent = () => {
    if (newEventDescription.trim() && newEventDate) {
      updateAppState({ lifeEvents: [...lifeEvents, { description: newEventDescription.trim(), date: newEventDate }] });
      setNewEventDescription('');
      setNewEventDate('');
