  const handleSendMessage = async (message: string) => {
    if (!currentChatSession) return;
    const newUserMsg: ChatMessage = { role: 'user', text: message };
    const newModelMsg: ChatMessage = { role: 'model', text: '' };
    setAppState(prev => ({ ...prev, chatHistory: [...prev.chatHistory, newUserMsg, newModelMsg] }));
    setChatLoading(true);
    let fullText = '';
    try {
