    const seenEvents = new Set<string>();
    const seenChat = new Set<string>();

    const addEvents = (events: any[]) => {
      if (!Array.isArray(events)) return;
      events.forEach(e => {
        const key = `${e.description || e.desc}-${e.date}`.toLowerCase().trim();
        if (key && !seenEvents.has(key)) {
          seenEvents.add(key);
          recoveredEvents.push({ description: e.description || e.desc, date: e.date });
        }
      });
    };

    const addChat = (history: any[]) => {
      if (!Array.isArray(history)) return;
      history.forEach(msg => {
        const key = `${msg.role}-${msg.text}`.trim();
        if (key && !seenChat.has(key)) {
          seenChat.has(key);
          recoveredChat.push(msg);
        }
      });
    };

    // 1. GLOBAL SCAN: Check every single key in localStorage for anything that looks like our data
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && (key.includes('cosmic') || key.includes('astrology') || key.includes('compass') || key.includes('reading'))) {
        try {
          const raw = localStorage.getItem(key);
          if (!raw) continue;
          const data = JSON.parse(raw);

          if (data.lifeEvents) addEvents(data.lifeEvents);
          if (data.chatHistory) addChat(data.chatHistory);
          if (data.history) addChat(data.history); // Handle older naming conventions
          if (data.events) addEvents(data.events); // Handle older naming conventions

          if (!recoveredBirth && data.birthDetails) recoveredBirth = data.birthDetails;
          if (!recoveredBirth && data.profile) recoveredBirth = data.profile;

          if (Object.keys(recoveredVisuals).length === 0 && data.visuals) recoveredVisuals = data.visuals;
        } catch (e) {
          // Key was not JSON, ignore
        }
      }
    }

    const defaultEvents: LifeEvent[] = [
      { description: 'Moved to Germany', date: '2024-11-06' },
      { description: 'Divorce Process / Life Shift', date: '2025-10-17' },
    ];

    if (recoveredEvents.length === 0) recoveredEvents = defaultEvents;

    return {
      birthDetails: recoveredBirth || {
        name: 'Harshkumar Panubhai Patel',
        dob: '1995-01-17',
        tob: '15:58',
        pob: 'Vadodara, Gujarat, India',
        rashi: 'Cancer',
      },
      readingOptions: {
        astrology: true,
        numerology: true,
        rashifal: true,
        jyotish: true,
        dailyHoroscope: true,
        palmistry: true,
        lalKitab: true,
        vasthu: true,
        faceReading: true,
      },
      advancedReadingOptions: {
        culturalContext: 'Vedic',
        includeScientificPerspective: true,
      },
      lifeEvents: recoveredEvents,
      outputLanguage: 'Gujarati',
      exSpouseDetails: { name: '', dob: '' },
      enableGoogleSearch: false,
      chatHistory: recoveredChat,
      visuals: recoveredVisuals
    };
  });

  const { birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, chatHistory, visuals } = appState;

  const [newEventDescription, setNewEventDescription] = useState<string>('');
  const [newEventDate, setNewEventDate] = useState<string>('');
  const [reading, setReading] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [groundingSources, setGroundingSources] = useState<ApiResponse['groundingSources']>([]);
  const [isChatMode, setIsChatMode] = useState<boolean>(false);
  const [currentChatSession, setCurrentChatSession] = useState<Chat | undefined>(undefined);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadSlot, setActiveUploadSlot] = useState<keyof Visuals | null>(null);

  // EFFECT: Fetch from Firebase and Sync
  useEffect(() => {
    const initFirebase = async () => {
      setIsRecovering(true);
      const remoteData = await loadFromFirebase(userId);
      if (remoteData) {
        setAppState(prev => {
          // Merge chat histories carefully
          const combinedChat = [...prev.chatHistory];
          const chatKeys = new Set(combinedChat.map(m => `${m.role}-${m.text}`));
          if (Array.isArray(remoteData.chatHistory)) {
            remoteData.chatHistory.forEach((msg: ChatMessage) => {
              if (!chatKeys.has(`${msg.role}-${msg.text}`)) combinedChat.push(msg);
            });
          }

          // Merge events carefully
          const combinedEvents = [...prev.lifeEvents];
          const eventKeys = new Set(combinedEvents.map(e => `${e.description}-${e.date}`));
          if (Array.isArray(remoteData.lifeEvents)) {
            remoteData.lifeEvents.forEach((e: LifeEvent) => {
              if (!eventKeys.has(`${e.description}-${e.date}`)) combinedEvents.push(e);
            });
          }

          return {
            ...prev,
            ...remoteData,
            lifeEvents: combinedEvents,
            chatHistory: combinedChat,
            // Only take remote birth details if local ones are the default
            birthDetails: prev.birthDetails.name === 'Harshkumar Panubhai Patel' ? (remoteData.birthDetails || prev.birthDetails) : prev.birthDetails
          };
        });
        setIsFirebaseSynced(true);
      }
      setIsRecovering(false);
    };
    initFirebase();
  }, [userId]);

  // EFFECT: Auto-sync
  useEffect(() => {
    saveStateToLocalStorage(CURRENT_STATE_KEY, appState);
    const timeoutId = setTimeout(() => {
      syncToFirebase(userId, appState).then(success => setIsFirebaseSynced(success));
    }, 3000); 
    return () => clearTimeout(timeoutId);
  }, [appState, userId]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    updateAppState({ birthDetails: { ...birthDetails, [name]: value } });
  };

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, checked } = e.target;
    updateAppState({ readingOptions: { ...readingOptions, [name]: checked } });
  };

  const handleFileUpload = (slot: keyof Visuals) => {
    setActiveUploadSlot(slot);
    fileInputRef.current?.click();
  };

  const compressImage = (base64Str: string, maxWidth = 450, maxHeight = 450): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64Str;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > height) {
          if (width > maxWidth) { height *= maxWidth / width; width = maxWidth; }
        } else {
          if (height > maxHeight) { width *= maxHeight / height; height = maxHeight; }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', 0.5));
      };
    });
  };

  const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeUploadSlot) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string);
        updateAppState({ visuals: { ...visuals, [activeUploadSlot]: compressed } });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddLifeEvent = () => {
    if (newEventDescription.trim() && newEventDate) {
      updateAppState({ lifeEvents: [...lifeEvents, { description: newEventDescription.trim(), date: newEventDate }] });
      setNewEventDescription('');
      setNewEventDate('');
    }
  };

  const handleRemoveLifeEvent = (index: number) => {
    updateAppState({ lifeEvents: lifeEvents.filter((_, i) => i !== index) });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals);
      setReading(result.reading);
      setGroundingSources(result.groundingSources || []);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const initializeChat = useCallback(async () => {
    setChatLoading(true);
    setChatError(null);
    try {
      const chat = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
      setCurrentChatSession(chat);
      if (chatHistory.length === 0) {
        setAppState(prev => ({
          ...prev,
          chatHistory: [{ role: 'model', text: `Namaste ${birthDetails.name}. All your past history has been found in your browser memory and synced to the cloud. How shall we proceed?` }]
        }));
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals, chatHistory]);

  const handleSendMessage = async (message: string) => {
    if (!currentChatSession) return;
    const newUserMsg: ChatMessage = { role: 'user', text: message };
    const newModelMsg: ChatMessage = { role: 'model', text: '' };
    setAppState(prev => ({ ...prev, chatHistory: [...prev.chatHistory, newUserMsg, newModelMsg] }));
    setChatLoading(true);
    let fullText = '';
    try {
      const stream = sendChatMessage(currentChatSession, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          if (hist.length > 0) hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  };

  const suggestedQuestions = useMemo(() => [
    "What do my palm lines say about my future prosperity?",
    "Explain the spiritual significance of my timeline events.",
    "Which Lal Kitab remedies are best for my current phase?",
    "Does my face structure indicate strong leadership qualities?"
  ], []);

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={onFileChange} />

      <header className="flex flex-col items-center mb-10">
        <h1 className="font-serif text-4xl md:text-5xl text-white mb-2 text-center bg-clip-text text-transparent bg-gradient-to-b from-white to-gray-500">Cosmic Compass</h1>
        <div className="flex items-center space-x-2">
          <span className={`w-2 h-2 rounded-full ${isFirebaseSynced ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-yellow-500 animate-pulse'}`}></span>
          <span className="text-[10px] uppercase tracking-widest text-gray-500 font-bold">
            {isRecovering ? 'Restoring Legacy Data...' : isFirebaseSynced ? 'Cloud Connected' : 'Connecting...'}
          </span>
        </div>
      </header>

      <div className="flex justify-center mb-10">
        <div className="glass p-1.5 rounded-2xl flex space-x-2 shadow-2xl">
          <button onClick={() => setIsChatMode(false)} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${!isChatMode ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Insights Center</button>
          <button onClick={() => { setIsChatMode(true); if (!currentChatSession) initializeChat(); }} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Cosmic Chat</button>
        </div>
      </div>

      {!isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-blue-400">✵</span> Birth Profile</h2>
              <div className="space-y-4">
                <InputField label="Name" id="name" type="text" value={birthDetails.name} onChange={handleInputChange} required />
                <div className="grid grid-cols-2 gap-4">
                  <InputField label="DOB" id="dob" type="date" value={birthDetails.dob} onChange={handleInputChange} required />
                  <InputField label="TOB" id="tob" type="time" value={birthDetails.tob} onChange={handleInputChange} required />
                </div>
                <InputField label="Place" id="pob" type="text" value={birthDetails.pob} onChange={handleInputChange} placeholder="City, Country" required />
                <InputField label="Rashi" id="rashi" type="text" value={birthDetails.rashi || ''} onChange={handleInputChange} placeholder="Moon Sign" required />
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5 shadow-2xl">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-purple-400">🧿</span> Visual Profile</h2>
              <div className="grid grid-cols-3 gap-3">
                {(['face', 'leftHand', 'rightHand'] as const).map(slot => (
                  <button
                    key={slot}
                    onClick={() => handleFileUpload(slot)}
                    className="relative group rounded-xl overflow-hidden aspect-square border-2 border-dashed border-white/10 hover:border-purple-500/50 transition-all bg-black/40 flex flex-col items-center justify-center shadow-inner"
                  >
                    {visuals[slot] ? (
                      <img src={visuals[slot]} className="w-full h-full object-cover" alt={slot} />
                    ) : (
                      <>
                        <span className="text-2xl mb-1">{slot === 'face' ? '👤' : '✋'}</span>
                        <span className="text-[8px] uppercase font-black text-gray-500 tracking-tighter text-center px-1">
                          {slot === 'face' ? 'Face' : slot === 'leftHand' ? 'Left Palm' : 'Right Palm'}
                        </span>
                      </>
                    )}
                    <div className="absolute inset-0 bg-purple-600/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <span className="text-[10px] font-bold text-white uppercase tracking-wider">Update</span>
                    </div>
                  </button>
                ))}
              </div>
            </section>
          </div>

          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5">
              <h2 className="font-serif text-2xl text-white mb-6 flex items-center"><span className="mr-3 text-yellow-400">📜</span> Ancient Sciences</h2>
              <div className="grid grid-cols-2 gap-2">
                {Object.keys(readingOptions).map((key) => (
