              <div className="space-y-3 mb-6 max-h-[400px] overflow-y-auto custom-scrollbar pr-1">
                {lifeEvents.map((event, i) => (
                  <div key={i} className="glass-dark p-3 rounded-xl flex justify-between items-center text-xs animate-in fade-in slide-in-from-left-2 duration-300">
                    <div className="flex-1 overflow-hidden mr-2">
                      <div className="font-semibold text-white truncate">{event.description}</div>
                      <div className="text-gray-400 text-[10px]">{event.date}</div>
                    </div>
                    <button onClick={() => handleRemoveLifeEvent(i)} className="text-red-400 hover:text-red-300 p-1 hover:bg-white/5 rounded transition-colors">✕</button>
                  </div>
                ))}
                {lifeEvents.length === 0 && <p className="text-center py-12 text-xs text-gray-500 italic">No history found.</p>}
              </div>
              <div className="space-y-3 pt-3 border-t border-white/10">
                <input className="w-full bg-black/30 border border-white/10 rounded-xl p-3 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all" placeholder="Add a past event..." value={newEventDescription} onChange={e => setNewEventDescription(e.target.value)} />
                <input type="date" className="w-full bg-black/30 border border-white/10 rounded-xl p-3 text-xs text-white focus:outline-none focus:ring-1 focus:ring-blue-500 transition-all" value={newEventDate} onChange={e => setNewEventDate(e.target.value)} />
                <button onClick={handleAddLifeEvent} className="w-full bg-blue-600/20 hover:bg-blue-600/30 text-blue-200 text-xs font-bold py-3 rounded-xl transition-all border border-blue-500/20">Record Milestone</button>
              </div>
            </section>
          </div>

          <div className="lg:col-span-4 flex flex-col h-full">
            <button onClick={handleSubmit} disabled={loading} className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold py-6 rounded-3xl shadow-2xl transition-all disabled:opacity-50 mb-6 flex items-center justify-center space-x-3 text-lg group">
              {loading ? (
                <><div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div><span>Gazing at the Cosmos...</span></>
              ) : (
                <><span>✨</span><span>Generate Omni Reading</span></>
              )}
            </button>

            {reading && (
              <div className="glass rounded-3xl p-6 border border-white/10 flex-1 overflow-y-auto max-h-[700px] animate-in fade-in zoom-in-95 duration-500 custom-scrollbar shadow-2xl">
                <h3 className="font-serif text-xl text-blue-300 mb-4 border-b border-white/10 pb-2 text-center">Celestial Wisdom</h3>
                <div className="text-gray-200 text-sm leading-relaxed space-y-4 whitespace-pre-wrap">{reading}</div>
                {groundingSources && groundingSources.length > 0 && (
                  <div className="mt-8 pt-4 border-t border-white/10">
                    <p className="text-[10px] text-gray-400 uppercase tracking-widest mb-3">Grounding Truths</p>
                    <div className="space-y-2">
                      {groundingSources.map((s, i) => (
                        <a key={i} href={s.web?.uri} target="_blank" rel="noopener noreferrer" className="block text-xs text-blue-400 hover:underline truncate">🔗 {s.web?.title || s.web?.uri}</a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
            {!reading && !loading && (
              <div className="glass rounded-3xl p-8 border border-white/5 flex-1 flex flex-col items-center justify-center text-center text-gray-500 min-h-[400px]">
                <div className="text-6xl mb-6 opacity-20">🧿</div>
                <p className="text-sm italic">"Consult the stars for your personalized life guide."</p>
                <p className="text-[10px] mt-4 uppercase tracking-[0.2em] text-blue-500/50 font-bold">
                  {lifeEvents.length} Life Milestones Synced
                </p>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="max-w-4xl mx-auto">
          <ChatInterface chatHistory={chatHistory} onSendMessage={handleSendMessage} loading={chatLoading} error={chatError} onBackToForm={() => setIsChatMode(false)} onClearChat={() => { updateAppState({ chatHistory: [] }); setCurrentChatSession(undefined); initializeChat(); }} suggestedQuestions={suggestedQuestions} />
        </div>
      )}
    </div>
  );
};

