/**
 * Gets or creates a persistent unique ID for this device/browser.
 */
export const getOrGenerateUserId = (): string => {
  let userId = localStorage.getItem('cosmic_user_id');
  if (!userId) {
    userId = 'user_' + Math.random().toString(36).substr(2, 9) + Date.now().toString(36);
    localStorage.setItem('cosmic_user_id', userId);
  }
  return userId;
};

/**
 * Saves the entire app state to Firebase.
 */
export const syncToFirebase = async (userId: string, data: any) => {
  try {
    const userRef = ref(db, `users/${userId}`);
    await set(userRef, {
      ...data,
      lastUpdated: new Date().toISOString()
    });
    return true;
  } catch (error) {
    console.error("Firebase Sync Error:", error);
    return false;
  }
};

/**
 * Fetches the app state from Firebase.
 */
export const loadFromFirebase = async (userId: string): Promise<any | null> => {
  try {
    const userRef = ref(db, `users/${userId}`);
    const snapshot = await get(userRef);
    if (snapshot.exists()) {
      return snapshot.val();
    }
    return null;
  } catch (error) {
    console.error("Firebase Load Error:", error);
    return null;
  }
};

import React, { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, ApiResponse, ChatMessage, Visuals } from './types';
import { getCombinedReading, initializeChatSession, sendChatMessage } from './services/geminiService';
import InputField from './components/InputField';
import CheckboxField from './components/CheckboxField';
import ChatInterface from './components/ChatInterface';
import { saveStateToLocalStorage, loadStateFromLocalStorage } from './utils/storage';
import { getOrGenerateUserId, syncToFirebase, loadFromFirebase } from './services/firebaseService';
import { Chat } from '@google/genai';

const CURRENT_STATE_KEY = 'cosmic_compass_master_v10_firebase';

interface AppState {
  birthDetails: BirthDetails;
  readingOptions: ReadingOptions;
  advancedReadingOptions: AdvancedReadingOptions;
  lifeEvents: LifeEvent[];
  outputLanguage: string;
  exSpouseDetails?: SpouseDetails;
  enableGoogleSearch: boolean;
  chatHistory: ChatMessage[];
  visuals: Visuals;
}

const App: React.FC = () => {
  const [isFirebaseSynced, setIsFirebaseSynced] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const userId = useMemo(() => getOrGenerateUserId(), []);

  // ATOMIC RECOVERY ENGINE: Scans every bit of local storage for patterns
  const [appState, setAppState] = useState<AppState>(() => {
    const recoveredEvents: LifeEvent[] = [];
    const recoveredChat: ChatMessage[] = [];
    let recoveredBirth: BirthDetails | null = null;
    let recoveredVisuals: Visuals = {};

    const seenEvents = new Set<string>();
    const seenChat = new Set<string>();

    const mineData = (obj: any) => {
      if (!obj || typeof obj !== 'object') return;

      // Detect Chat Patterns (role + text)
      if (obj.role && (obj.text || obj.content || obj.message)) {
        const text = obj.text || obj.content || obj.message;
        const key = `${obj.role}-${text}`.trim();
        if (text && !seenChat.has(key)) {
          seenChat.add(key);
          recoveredChat.push({ role: obj.role === 'assistant' ? 'model' : obj.role, text });
        }
      }

      // Detect Event Patterns (description + date)
      if ((obj.description || obj.desc || obj.event) && obj.date) {
        const desc = obj.description || obj.desc || obj.event;
        const key = `${desc}-${obj.date}`.toLowerCase().trim();
        if (key && !seenEvents.has(key)) {
          seenEvents.add(key);
          recoveredEvents.push({ description: desc, date: obj.date });
        }
      }

      // Detect Birth Profile Patterns
      if (obj.dob && obj.tob && obj.pob && !recoveredBirth) {
        recoveredBirth = {
          name: obj.name || 'Harshkumar Panubhai Patel',
          dob: obj.dob,
          tob: obj.tob,
          pob: obj.pob,
          rashi: obj.rashi
        };
      }

      // Detect Visuals
      if (obj.face || obj.leftHand || obj.rightHand) {
        recoveredVisuals = { ...recoveredVisuals, ...obj };
      }

      // Recurse into arrays/objects
      Object.values(obj).forEach(val => {
        if (val && typeof val === 'object') mineData(val);
      });
    };

