/**
 * Saves the entire app state to Firebase.
 */
export const syncToFirebase = async (userId: string, data: any) => {
  try {
    const userRef = ref(db, `users/${userId}`);
    await set(userRef, {
      ...data,
      lastUpdated: new Date().toISOString()
    });
    return true;
  } catch (error) {
    console.error("Firebase Sync Error:", error);
    return false;
  }
};

/**
 * Fetches the app state from Firebase.
 */
export const loadFromFirebase = async (userId: string): Promise<any | null> => {
  try {
    const userRef = ref(db, `users/${userId}`);
    const snapshot = await get(userRef);
    if (snapshot.exists()) {
      return snapshot.val();
    }
    return null;
  } catch (error) {
    console.error("Firebase Load Error:", error);
    return null;
  }
};

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, ApiResponse, Visuals, ChatMessage } from "../types";

function buildAstrologyPrompt(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  visuals?: Visuals,
  isChatContext: boolean = false
): string {
  const today = new Date();
  const dateString = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  let prompt = isChatContext 
    ? `You are an Omni-Esoteric Master. You possess deep knowledge of Astrology, Numerology, Jyotish, Palmistry, Lal Kitab, Vasthu Shastra, and Face Reading. Provide detailed, mystical, and accurate readings.`
    : `Generate a holistic esoteric reading based on birth data, ancient sciences, visual analysis, and life history.`;

  if (outputLanguage === 'Gujarati') {
    prompt += ` The entire response MUST be in the Gujarati language using authentic spiritual terminology.`;
  } else {
    prompt += ` The response should be in ${outputLanguage}.`;
  }

  prompt += `\n\nUser Profile:
- Name: ${birthDetails.name}
- Born: ${birthDetails.dob} at ${birthDetails.tob} in ${birthDetails.pob}
${birthDetails.rashi ? `- Rashi: ${birthDetails.rashi}` : ''}`;

  if (exSpouseDetails?.name) {
    prompt += `\n\nRelationship Context: Ex-spouse ${exSpouseDetails.name} (DOB: ${exSpouseDetails.dob}). Use this for karmic relationship analysis.`;
  }

  prompt += `\n\nRequested Disciplines:`;
  if (options.dailyHoroscope) prompt += `\n- Daily Guidance for ${dateString}`;
  if (options.astrology) prompt += `\n- Western Astrology (Signs & Aspects)`;
  if (options.numerology) prompt += `\n- Numerology (Life Path, Destiny Number)`;
  if (options.jyotish) prompt += `\n- Vedic Jyotish (Dashas, Nakshatras)`;
  if (options.palmistry) prompt += `\n- Palmistry (Actual visual analysis of provided hand images)`;
  if (options.lalKitab) prompt += `\n- Lal Kitab (House-based remedies and "Blind Planets")`;
  if (options.vasthu) prompt += `\n- Vasthu Shastra (Home energy and spatial alignment)`;
  if (options.faceReading) prompt += `\n- Face Reading (Visual analysis of facial features/Physiognomy)`;

  if (lifeEvents.length > 0) {
    prompt += `\n\nLife Timeline (Extremely Important Context):`;
    lifeEvents.forEach(e => prompt += `\n- ${e.description} (${e.date})`);
  }

  prompt += `\n\nAnalysis Requirements:
1. Synthesize all active disciplines into a unified life path.
2. Provide specific Lal Kitab remedies (Upay).
3. Suggest Vasthu corrections for their current living space.
4. Analyze the "Why" behind the recorded past life events using Dashas and planetary transits.
5. If palm images are provided, visually inspect the Heart, Life, and Head lines.
6. If a face image is provided, perform detailed face reading (eyebrows, eyes, chin, forehead).
7. Predict future windows for career, health, and personal growth.`;

  return prompt;
}

function getPartFromImage(dataUri: string) {
  const [header, data] = dataUri.split(',');
  const mimeType = header.match(/:(.*?);/)?.[1] || 'image/png';
  return {
    inlineData: {
      mimeType,
      data
    }
  };
}

export async function getCombinedReading(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  enableGoogleSearch: boolean = false,
  visuals?: Visuals
): Promise<ApiResponse> {
  // Create a new GoogleGenAI instance right before making an API call to ensure it always uses the most up-to-date API key
  const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
  const textPrompt = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, visuals, false);

  const parts: any[] = [{ text: textPrompt }];
  if (visuals?.face) parts.push(getPartFromImage(visuals.face));
  if (visuals?.leftHand) parts.push(getPartFromImage(visuals.leftHand));
  if (visuals?.rightHand) parts.push(getPartFromImage(visuals.rightHand));

  const modelConfig: any = {
    temperature: 0.8,
  };

  // The googleSearch tool is only available for gemini-3-pro-image-preview in multimodal contexts
  if (enableGoogleSearch) modelConfig.tools = [{ googleSearch: {} }];

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: modelConfig,
    });
    // Access .text property directly and extract grounding chunks for search grounding
    return { 
      reading: response.text || "Connection to stars lost.", 
      groundingSources: response.candidates?.[0]?.groundingMetadata?.groundingChunks as any 
    };
  } catch (error: any) {
    // Re-throw to handle specific "Requested entity was not found." in the UI
    throw error;
  }
}

export async function initializeChatSession(
  birthDetails: BirthDetails,
  options: ReadingOptions,
  advancedOptions: AdvancedReadingOptions,
  lifeEvents: LifeEvent[],
  outputLanguage: string,
  history: ChatMessage[] = [],
  exSpouseDetails?: SpouseDetails,
  enableGoogleSearch: boolean = false,
  visuals?: Visuals
): Promise<Chat> {
  // Create a new GoogleGenAI instance right before making an API call
  const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
  const systemInstruction = buildAstrologyPrompt(birthDetails, options, advancedOptions, lifeEvents, outputLanguage, exSpouseDetails, visuals, true);

  // Convert ChatMessage[] to the format Gemini expects for history
  const geminiHistory = history
    .filter(msg => msg.text && msg.text.trim()) 
    .map(msg => ({
      role: msg.role,
      parts: [{ text: msg.text }]
    }));

  return ai.chats.create({
    model: 'gemini-3-pro-image-preview',
    history: geminiHistory,
    config: {
      systemInstruction,
      temperature: 0.9,
    },
  });
}

export async function* sendChatMessage(chatSession: Chat, message: string): AsyncGenerator<string, void, unknown> {
  // Use sendMessageStream with the message parameter and access .text directly
  const responseStream = await chatSession.sendMessageStream({ message });
  for await (const chunk of responseStream) {
    const c = chunk as GenerateContentResponse;
    if (c.text) yield c.text;
  }
}

import React, { useState, useCallback, useEffect, useMemo, useRef } from 'react';
