  useEffect(() => {
    const initFirebase = async () => {
      setIsRecovering(true);
      const remoteData = await loadFromFirebase(userId);
      if (remoteData) { setAppState(prev => ({ ...prev, ...remoteData })); setIsFirebaseSynced(true); }
      setIsRecovering(false);
    };
    initFirebase();
  }, [userId]);

  const triggerSync = useCallback(async (data: AppState) => {
    setIsSyncing(true);
    const success = await syncToFirebase(userId, data);
    setIsFirebaseSynced(success);
    setIsSyncing(false);
  }, [userId]);

  useEffect(() => {
    saveStateToLocalStorage(CURRENT_STATE_KEY, appState);
    const timer = setTimeout(() => triggerSync(appState), 1500);
    return () => clearTimeout(timer);
  }, [appState, triggerSync]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
    setIsFirebaseSynced(false);
  }, []);

  const handleFileUpload = (slot: keyof Visuals) => {
    setActiveUploadSlot(slot);
    fileInputRef.current?.click();
  };

  const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeUploadSlot) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = (base64: string): Promise<string> => new Promise(res => {
          const img = new Image(); img.src = base64; img.onload = () => {
            const canvas = document.createElement('canvas'); canvas.width = 600; canvas.height = 600;
            canvas.getContext('2d')?.drawImage(img, 0, 0, 600, 600); res(canvas.toDataURL('image/jpeg', 0.6));
          };
        });
        const finalImg = await compressed(reader.result as string);
        const newVisuals = { ...visuals, [activeUploadSlot]: finalImg };
        updateAppState({ visuals: newVisuals });
        triggerSync({ ...appState, visuals: newVisuals });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true); setError(null);
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals);
      setReading(result.reading);
    } catch (err: any) { setError(err.message); } finally { setLoading(false); }
  };

  const initializeChat = useCallback(async () => {
    setChatLoading(true);
    setChatError(null);
    try {
      const chat = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
      setCurrentChatSession(chat);
      if (chatHistory.length === 0) {
        updateAppState({
          chatHistory: [{ role: 'model', text: `Namaste ${birthDetails.name}. Your visual profile and timeline are archived. What shall we explore today?` }]
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals, updateAppState]);

  const handleSendMessage = async (message: string) => {
    let session = currentChatSession;
    if (!session) {
      setChatLoading(true);
      try {
        session = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
        setCurrentChatSession(session);
      } catch (err: any) {
        setChatError(err.message);
        setChatLoading(false);
        return;
      }
    }

    const newUserMsg: ChatMessage = { role: 'user', text: message };
    const newModelMsg: ChatMessage = { role: 'model', text: '' };
    setAppState(prev => ({ ...prev, chatHistory: [...prev.chatHistory, newUserMsg, newModelMsg] }));
    setChatLoading(true);

    let fullText = '';
    try {
      const stream = sendChatMessage(session, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          if (hist.length > 0) hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }
    } catch (err: any) {
      setChatError(err.message);
    } finally {
      setChatLoading(false);
    }
  };

  const visualsCount = Object.values(visuals).filter(Boolean).length;

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={onFileChange} />
      <header className="flex flex-col items-center mb-10">
        <h1 className="font-serif text-4xl md:text-5xl text-white mb-2 text-center bg-clip-text text-transparent bg-gradient-to-b from-white to-gray-500 font-bold tracking-tight">Cosmic Compass</h1>
        <div className="flex items-center space-x-3">
          <div className="flex items-center space-x-1.5 px-3 py-1 bg-white/5 rounded-full border border-white/10">
            <span className={`w-1.5 h-1.5 rounded-full ${isFirebaseSynced ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]' : 'bg-yellow-500 animate-pulse'}`}></span>
            <span className="text-[9px] uppercase tracking-tighter text-gray-400 font-bold">
              {isRecovering ? 'Restoring Profile...' : isFirebaseSynced ? `Cloud Secure` : 'Syncing Profile...'}
            </span>
          </div>
          {visualsCount > 0 && (
            <div className="flex items-center space-x-1.5 px-3 py-1 bg-blue-500/10 rounded-full border border-blue-500/20 animate-pulse">
              <span className="text-[9px] uppercase tracking-tighter text-blue-400 font-black">Vision: ACTIVE ({visualsCount}/3)</span>
            </div>
          )}
        </div>
      </header>

      {/* CHAT OPTION BUTTONS */}
      <div className="flex justify-center mb-10">
        <div className="glass p-1.5 rounded-2xl flex space-x-2 shadow-2xl relative">
          <button onClick={() => setIsChatMode(false)} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${!isChatMode ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Insights Center</button>
          <button 
            onClick={() => { setIsChatMode(true); if (!currentChatSession) initializeChat(); }} 
            className={`px-8 py-2.5 rounded-xl font-bold transition-all relative ${isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'} ${visualsCount > 0 && !isChatMode ? 'ring-2 ring-purple-500/50 ring-offset-2 ring-offset-transparent animate-pulse' : ''}`}
          >
            Cosmic Chat
            {visualsCount > 0 && !isChatMode && (
              <span className="absolute -top-1 -right-1 bg-blue-500 text-[6px] px-1.5 py-0.5 rounded-full font-black animate-bounce shadow-lg">VISION READY</span>
            )}
          </button>
        </div>
      </div>

      {!isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5 shadow-xl">
