                <div className="grid grid-cols-2 gap-4">
                  <InputField label="DOB" id="dob" type="date" value={birthDetails.dob} onChange={e => updateAppState({ birthDetails: { ...birthDetails, dob: e.target.value } })} required />
                  <InputField label="TOB" id="tob" type="time" value={birthDetails.tob} onChange={e => updateAppState({ birthDetails: { ...birthDetails, tob: e.target.value } })} required />
                </div>
                <InputField label="Place" id="pob" type="text" value={birthDetails.pob} onChange={e => updateAppState({ birthDetails: { ...birthDetails, pob: e.target.value } })} placeholder="City, Country" required />
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5 shadow-2xl overflow-hidden relative">
              <div className="absolute top-0 right-0 p-3">
                <span className="text-[8px] font-black text-blue-500 bg-blue-500/10 px-2 py-0.5 rounded-full border border-blue-500/20">MULTIMODAL READY</span>
