                onClick={handleSend}
                disabled={loading || !currentInput.trim()}
                className="absolute right-2 p-2 bg-blue-600 hover:bg-blue-500 text-white rounded-xl shadow-lg transition-all disabled:opacity-50"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

// App.tsx

import React, { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import { BirthDetails, ReadingOptions, AdvancedReadingOptions, LifeEvent, SpouseDetails, ApiResponse, ChatMessage, Visuals } from './types';
import { getCombinedReading, initializeChatSession, sendChatMessage } from './services/geminiService';
import InputField from './components/InputField';
import CheckboxField from './components/CheckboxField';
import ChatInterface from './components/ChatInterface';
import { saveStateToLocalStorage } from './utils/storage';
import { getOrGenerateUserId, syncToFirebase, loadFromFirebase } from './services/firebaseService';
import { Chat } from '@google/genai';

const CURRENT_STATE_KEY = 'cosmic_compass_v24_hard_sync';

interface AppState {
  birthDetails: BirthDetails;
  readingOptions: ReadingOptions;
  advancedReadingOptions: AdvancedReadingOptions;
  lifeEvents: LifeEvent[];
  outputLanguage: string;
  exSpouseDetails?: SpouseDetails;
  enableGoogleSearch: boolean;
  chatHistory: ChatMessage[];
  visuals: Visuals;
}

const App: React.FC = () => {
  const [isFirebaseSynced, setIsFirebaseSynced] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [hasRestoredFromCloud, setHasRestoredFromCloud] = useState(false);
  const [restoredCount, setRestoredCount] = useState(0);
  const userId = useMemo(() => getOrGenerateUserId(), []);

  const [newEventDesc, setNewEventDesc] = useState('');
  const [newEventDate, setNewEventDate] = useState('');

  const [appState, setAppState] = useState<AppState>(() => {
    return {
      birthDetails: { name: 'Harshkumar Panubhai Patel', dob: '1995-01-17', tob: '15:58', pob: 'Vadodara, Gujarat, India', rashi: 'Cancer' },
      readingOptions: { astrology: true, numerology: true, rashifal: true, jyotish: true, dailyHoroscope: true, palmistry: true, lalKitab: true, vasthu: true, faceReading: true },
      advancedReadingOptions: { culturalContext: 'Vedic', includeScientificPerspective: true },
      lifeEvents: [
        { description: 'Admitted: Platelets down to 10,000', date: '2021-08-24' },
        { description: 'Married to Pankti Patel', date: '2022-01-04' },
        { description: 'Admitted: Excess lead level 269ug/ml', date: '2023-10-20' },
        { description: 'Moved to Germany', date: '2024-11-06' },
        { description: 'Joined Amazon as a driver', date: '2024-12-04' },
        { description: 'Left Amazon job (Small Accident)', date: '2025-01-04' },
        { description: 'Driving trial at Bellabona', date: '2025-01-17' },
        { description: 'Joined Bellabona as driver', date: '2025-01-20' },
        { description: 'Theft: Bag stolen from car', date: '2025-01-21' },
        { description: 'Logistic Manager at Bellabona', date: '2025-05-05' },
        { description: 'Shifted to new rental house', date: '2025-08-08' },
        { description: 'Divorce finalized', date: '2025-10-17' },
        { description: 'Visa extended till 2027', date: '2025-11-17' },
        { description: 'MacBook purchase', date: '2025-12-20' },
      ],
      outputLanguage: 'Gujarati',
      exSpouseDetails: { name: 'Pankti Patel', dob: '1998-10-17' },
      enableGoogleSearch: false,
      chatHistory: [],
      visuals: {}
    };
  });

  const { birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, chatHistory, visuals } = appState;

  const [reading, setReading] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isChatMode, setIsChatMode] = useState<boolean>(false);
  const [currentChatSession, setCurrentChatSession] = useState<Chat | undefined>(undefined);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadSlot, setActiveUploadSlot] = useState<keyof Visuals | null>(null);

  // CLOUD RESTORATION - CRITICAL SYNC LOCK
  useEffect(() => {
    const initFirebase = async () => {
      setIsRecovering(true);
      try {
        const remoteData = await loadFromFirebase(userId);
        if (remoteData) {
          const vCount = Object.keys(remoteData.visuals || {}).length;
          const hCount = (remoteData.chatHistory || []).length;

          setAppState(prev => ({
            ...prev,
            ...remoteData,
            // Ensure lists are prioritized from cloud and merged correctly
            lifeEvents: remoteData.lifeEvents || prev.lifeEvents,
            chatHistory: remoteData.chatHistory || prev.chatHistory,
            visuals: remoteData.visuals || prev.visuals
          }));

          setRestoredCount(vCount + hCount);
          setIsFirebaseSynced(true);
          console.log(`[Cosmic] Restored ${hCount} chat messages and ${vCount} artifacts.`);
        }
      } catch (e) {
        console.error("Cloud failure:", e);
      } finally {
        setIsRecovering(false);
        setHasRestoredFromCloud(true); // Unlock syncing only after attempt to load
      }
    };
    initFirebase();
  }, [userId]);

  const triggerSync = useCallback(async (data: AppState) => {
    if (!hasRestoredFromCloud) return false;

    // Safety Guard: Don't sync an empty history if we already have one unless explicitly reset
    if (chatHistory.length > 0 && data.chatHistory.length === 0 && !isChatMode) {
        console.warn("[Cosmic] Prevented potential data loss during sync.");
        return false;
    }

    setIsSyncing(true);
    const success = await syncToFirebase(userId, data);
    setIsFirebaseSynced(success);
    setIsSyncing(false);
    return success;
  }, [userId, hasRestoredFromCloud, chatHistory.length, isChatMode]);

  // Debounced Syncing for general form changes
  useEffect(() => {
    saveStateToLocalStorage(CURRENT_STATE_KEY, appState);
    const timer = setTimeout(() => {
      if (hasRestoredFromCloud) triggerSync(appState);
    }, 10000); // Relaxed background sync
    return () => clearTimeout(timer);
  }, [appState, triggerSync, hasRestoredFromCloud]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
    setIsFirebaseSynced(false);
  }, []);

  const addLifeEvent = () => {
    if (newEventDesc && newEventDate) {
      const updatedEvents = [...lifeEvents, { description: newEventDesc, date: newEventDate }];
      updatedEvents.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
      updateAppState({ lifeEvents: updatedEvents });
      setNewEventDesc('');
      setNewEventDate('');
    }
  };

  const removeLifeEvent = (index: number) => {
    const updatedEvents = lifeEvents.filter((_, i) => i !== index);
    updateAppState({ lifeEvents: updatedEvents });
  };

  const handleSubmit = useCallback(async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setLoading(true); setError(null); setReading('');
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals);
      setReading(result.reading);
    } catch (err: any) {
      setError(err.message || "Synthesis interrupted.");
    } finally { setLoading(false); }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals]);

  const initializeChat = useCallback(async () => {
    if (currentChatSession) return;
    setChatLoading(true); setChatError(null);
    try {
      const session = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
      setCurrentChatSession(session);
    } catch (err: any) { setChatError(err.message); } finally { setChatLoading(false); }
  }, [currentChatSession, birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals]);

  const handleSendMessage = async (message: string) => {
    let session = currentChatSession;
    if (!session) {
      setChatLoading(true);
      try {
        session = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
        setCurrentChatSession(session);
      } catch (err: any) { setChatError(err.message); setChatLoading(false); return; }
    }

    const newUserMsg: ChatMessage = { role: 'user', text: message };
    const newModelMsg: ChatMessage = { role: 'model', text: '' };

    // 1. Update local state with user message
    const historyWithUser = [...chatHistory, newUserMsg];
    setAppState(prev => ({ ...prev, chatHistory: [...historyWithUser, newModelMsg] }));
    setChatLoading(true);

    let fullText = '';
    try {
      const stream = sendChatMessage(session, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          if (hist.length > 0) hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }

      // 2. ATOMIC SYNC: Force save now that the AI has finished its turn
      const finalHistory = [...historyWithUser, { role: 'model' as const, text: fullText }];
      const finalStateToSync = { ...appState, chatHistory: finalHistory };

      setAppState(finalStateToSync);
      await triggerSync(finalStateToSync); 

    } catch (err: any) { 
      setChatError(err.message); 
    } finally { 
      setChatLoading(false); 
    }
  };

  const clearChat = () => {
    if (window.confirm("Are you sure you want to clear your Cosmic Oracle history?")) {
        updateAppState({ chatHistory: [] });
        setCurrentChatSession(undefined);
        // Explicit sync to clear cloud too
        if (hasRestoredFromCloud) syncToFirebase(userId, { ...appState, chatHistory: [] });
    }
  };

  return (
    <div className="max-w-6xl mx-auto py-8 px-4">
      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
        const file = e.target.files?.[0];
        if (file && activeUploadSlot) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const newVisuals = { ...visuals, [activeUploadSlot]: reader.result as string };
                updateAppState({ visuals: newVisuals });
                if (hasRestoredFromCloud) triggerSync({ ...appState, visuals: newVisuals });
            };
            reader.readAsDataURL(file);
        }
      }} />

      {restoredCount > 0 && isFirebaseSynced && !isRecovering && (
        <div className="fixed top-4 right-4 z-50 animate-in fade-in slide-in-from-top-4 duration-1000">
          <div className="bg-indigo-600/90 backdrop-blur-xl text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl border border-white/20 flex items-center space-x-3">
            <span>Archive Active ({restoredCount})</span>
          </div>
        </div>
      )}

      <header className="flex flex-col items-center mb-10">
        <h1 className="font-serif text-4xl md:text-5xl text-white mb-2 text-center bg-clip-text text-transparent bg-gradient-to-b from-white to-gray-500 font-bold tracking-tight">Cosmic Compass</h1>
        <div className="flex items-center space-x-3">
          <div className={`flex items-center space-x-1.5 px-3 py-1 rounded-full border transition-all ${isFirebaseSynced ? 'bg-green-500/10 border-green-500/30' : 'bg-yellow-500/10 border-yellow-500/30'}`}>
            <span className={`w-1.5 h-1.5 rounded-full ${isFirebaseSynced ? 'bg-green-500' : 'bg-yellow-500 animate-pulse'}`}></span>
            <span className="text-[9px] uppercase tracking-tighter text-gray-300 font-black">
              {isRecovering ? 'Restoring Archive...' : isFirebaseSynced ? 'Cloud Synced' : 'Connecting...'}
            </span>
          </div>
          <select value={outputLanguage} onChange={e => updateAppState({ outputLanguage: e.target.value })} className="bg-white/5 border border-white/10 rounded-full px-3 py-1 text-[10px] font-bold text-blue-300">
            <option value="English">English</option>
            <option value="Gujarati">Gujarati</option>
          </select>
        </div>
      </header>

      <div className="flex justify-center mb-10">
        <div className="glass p-1.5 rounded-2xl flex space-x-2 shadow-2xl relative">
          <button onClick={() => setIsChatMode(false)} className={`px-8 py-2.5 rounded-xl font-bold transition-all ${!isChatMode ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Insights</button>
          <button 
            onClick={() => { if (isRecovering) return; setIsChatMode(true); if (!currentChatSession) initializeChat(); }} 
            className={`px-8 py-2.5 rounded-xl font-bold transition-all relative ${isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
            disabled={isRecovering}
          >
            Oracle Chat
          </button>
        </div>
      </div>

      {!isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-3xl p-6 border border-white/5 shadow-xl">
              <h2 className="font-serif text-xl text-white mb-6">Profile</h2>
              <div className="space-y-4">
                <InputField label="Name" id="name" type="text" value={birthDetails.name} onChange={e => updateAppState({ birthDetails: { ...birthDetails, name: e.target.value } })} />
                <div className="grid grid-cols-2 gap-4">
                  <InputField label="DOB" id="dob" type="date" value={birthDetails.dob} onChange={e => updateAppState({ birthDetails: { ...birthDetails, dob: e.target.value } })} />
                  <InputField label="TOB" id="tob" type="time" value={birthDetails.tob} onChange={e => updateAppState({ birthDetails: { ...birthDetails, tob: e.target.value } })} />
                </div>
                <InputField label="Place" id="pob" type="text" value={birthDetails.pob} onChange={e => updateAppState({ birthDetails: { ...birthDetails, pob: e.target.value } })} />
              </div>
            </section>

            <section className="glass rounded-3xl p-6 border border-white/5 shadow-2xl">
              <h2 className="font-serif text-xl text-white mb-6">Vision Artifacts</h2>
              <div className="grid grid-cols-3 gap-3">
                {(['face', 'leftHand', 'rightHand'] as const).map(slot => (
                  <button key={slot} onClick={() => { setActiveUploadSlot(slot); fileInputRef.current?.click(); }} className={`relative rounded-xl overflow-hidden aspect-square border transition-all flex items-center justify-center ${visuals[slot] ? 'border-blue-500 shadow-lg' : 'border-white/10 bg-black/40 hover:border-blue-500/50'}`}>
                    {visuals[slot] ? <img src={visuals[slot]} className="w-full h-full object-cover" /> : <span className="text-xl opacity-40">{slot === 'face' ? '👤' : '✋'}</span>}
                  </button>
                ))}
              </div>
