const App: React.FC = () => {
  const [isFirebaseSynced, setIsFirebaseSynced] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isRecovering, setIsRecovering] = useState(false);
  const [hasRestoredFromCloud, setHasRestoredFromCloud] = useState(false);
  const [restoredCount, setRestoredCount] = useState(0);
  const userId = useMemo(() => getOrGenerateUserId(), []);

  const [newEventDesc, setNewEventDesc] = useState('');
  const [newEventDate, setNewEventDate] = useState('');

  const [appState, setAppState] = useState<AppState>(() => {
    return {
      birthDetails: { name: 'Harshkumar Panubhai Patel', dob: '1995-01-17', tob: '15:58', pob: 'Vadodara, Gujarat, India', rashi: 'Cancer' },
      readingOptions: { astrology: true, numerology: true, rashifal: true, jyotish: true, dailyHoroscope: true, palmistry: true, lalKitab: true, vasthu: true, faceReading: true },
      advancedReadingOptions: { culturalContext: 'Vedic', includeScientificPerspective: true },
      lifeEvents: [
        { description: 'Admitted: Platelets down to 10,000', date: '2021-08-24' },
        { description: 'Married to Pankti Patel', date: '2022-01-04' },
        { description: 'Admitted: Excess lead level 269ug/ml', date: '2023-10-20' },
        { description: 'Moved to Germany', date: '2024-11-06' },
        { description: 'Joined Amazon as a driver', date: '2024-12-04' },
        { description: 'Left Amazon job (Small Accident)', date: '2025-01-04' },
        { description: 'Driving trial at Bellabona', date: '2025-01-17' },
        { description: 'Joined Bellabona as driver', date: '2025-01-20' },
        { description: 'Theft: Bag stolen from car', date: '2025-01-21' },
        { description: 'Logistic Manager at Bellabona', date: '2025-05-05' },
        { description: 'Shifted to new rental house', date: '2025-08-08' },
        { description: 'Divorce finalized', date: '2025-10-17' },
        { description: 'Visa extended till 2027', date: '2025-11-17' },
        { description: 'MacBook purchase', date: '2025-12-20' },
      ],
      outputLanguage: 'Gujarati',
      exSpouseDetails: { name: 'Pankti Patel', dob: '1995-01-01' },
      enableGoogleSearch: false,
      chatHistory: [],
      visuals: {}
    };
  });

  const { birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, chatHistory, visuals } = appState;

  const [reading, setReading] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isChatMode, setIsChatMode] = useState<boolean>(false);
  const [currentChatSession, setCurrentChatSession] = useState<Chat | undefined>(undefined);
  const [chatLoading, setChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadSlot, setActiveUploadSlot] = useState<keyof Visuals | null>(null);

  // CLOUD RESTORATION - CRITICAL SYNC LOCK
  useEffect(() => {
    const initFirebase = async () => {
      setIsRecovering(true);
      try {
        const remoteData = await loadFromFirebase(userId);
        if (remoteData) {
          const vCount = Object.keys(remoteData.visuals || {}).length;
          const hCount = (remoteData.chatHistory || []).length;

          setAppState(prev => ({
            ...prev,
            ...remoteData,
            // Ensure lists are prioritized from cloud and merged correctly
            lifeEvents: remoteData.lifeEvents && remoteData.lifeEvents.length > 0 ? remoteData.lifeEvents : prev.lifeEvents,
            chatHistory: remoteData.chatHistory || [],
            visuals: remoteData.visuals || {}
          }));

          setRestoredCount(vCount + hCount);
          setIsFirebaseSynced(true);
          console.log(`[Cosmic] Restored soul history with ${hCount} messages.`);
        }
      } catch (e) {
        console.error("Cloud failure:", e);
      } finally {
        setIsRecovering(false);
        setHasRestoredFromCloud(true); // Only unlock after this completes
      }
    };
    initFirebase();
  }, [userId]);

  const triggerSync = useCallback(async (data: AppState) => {
    // PROTECTIVE GATE: Never sync if we haven't successfully checked the cloud yet
    if (!hasRestoredFromCloud) return false;

    setIsSyncing(true);
    const success = await syncToFirebase(userId, data);
    setIsFirebaseSynced(success);
    setIsSyncing(false);
    return success;
  }, [userId, hasRestoredFromCloud]);

  // General state change sync (debounced)
  useEffect(() => {
    saveStateToLocalStorage(CURRENT_STATE_KEY, appState);
    const timer = setTimeout(() => {
      if (hasRestoredFromCloud) triggerSync(appState);
    }, 8000);
    return () => clearTimeout(timer);
  }, [appState, triggerSync, hasRestoredFromCloud]);

  const updateAppState = useCallback((updates: Partial<AppState>) => {
    setAppState((prevState) => ({ ...prevState, ...updates }));
    setIsFirebaseSynced(false);
  }, []);

  const addLifeEvent = () => {
    if (newEventDesc && newEventDate) {
      const updatedEvents = [...lifeEvents, { description: newEventDesc, date: newEventDate }];
      updatedEvents.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
      updateAppState({ lifeEvents: updatedEvents });
      setNewEventDesc('');
      setNewEventDate('');
    }
  };

  const removeLifeEvent = (index: number) => {
    const updatedEvents = lifeEvents.filter((_, i) => i !== index);
    updateAppState({ lifeEvents: updatedEvents });
  };

  const handleSubmit = useCallback(async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setLoading(true); setError(null); setReading('');
    try {
      const result = await getCombinedReading(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals);
      setReading(result.reading);
    } catch (err: any) {
      setError(err.message || "Synthesis interrupted.");
    } finally { setLoading(false); }
  }, [birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, exSpouseDetails, enableGoogleSearch, visuals]);

  const initializeChat = useCallback(async () => {
    if (currentChatSession) return;
    setChatLoading(true); setChatError(null);
    try {
      const session = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
      setCurrentChatSession(session);
    } catch (err: any) { setChatError(err.message); } finally { setChatLoading(false); }
  }, [currentChatSession, birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals]);

  const handleSendMessage = async (message: string) => {
    let session = currentChatSession;
    if (!session) {
      setChatLoading(true);
      try {
        session = await initializeChatSession(birthDetails, readingOptions, advancedReadingOptions, lifeEvents, outputLanguage, chatHistory, exSpouseDetails, enableGoogleSearch, visuals);
        setCurrentChatSession(session);
      } catch (err: any) { setChatError(err.message); setChatLoading(false); return; }
    }

    const newUserMsg: ChatMessage = { role: 'user', text: message };
    const newModelMsg: ChatMessage = { role: 'model', text: '' };

    // Add user message locally
    const historyWithUser = [...chatHistory, newUserMsg];
    setAppState(prev => ({ ...prev, chatHistory: [...historyWithUser, newModelMsg] }));
    setChatLoading(true);

    let fullText = '';
    try {
      const stream = sendChatMessage(session, message);
      for await (const chunk of stream) {
        fullText += chunk;
        setAppState(prev => {
          const hist = [...prev.chatHistory];
          if (hist.length > 0) hist[hist.length - 1].text = fullText;
          return { ...prev, chatHistory: hist };
        });
      }

      // FINAL ATOMIC SAVE: Push the complete state to Firebase immediately
      const finalChatHistory = [...historyWithUser, { role: 'model', text: fullText }];
      const finalState = { ...appState, chatHistory: finalChatHistory };

      setAppState(finalState);
      triggerSync(finalState); 

    } catch (err: any) { 
      setChatError(err.message); 
    } finally { 
      setChatLoading(false); 
    }
  };

  const clearChat = () => {
    if (window.confirm("Delete Oracle Archive? This cannot be undone.")) {
      updateAppState({ chatHistory: [] });
      setCurrentChatSession(undefined);
      if (hasRestoredFromCloud) triggerSync({ ...appState, chatHistory: [] });
    }
  };

