  birthDetails: BirthDetails;
  lifeEvents: LifeEvent[];
  outputLanguage: string;
  enableGoogleSearch: boolean;
  chatHistory: ChatMessage[];
  lastReading: string;
}

// --- Global Config ---

const MASTER_STORAGE_KEY = 'cosmic_compass_v4';
const LATEST_FLASH_MODEL = 'gemini-3-flash-preview';

const firebaseConfig = {
  apiKey: "AIzaSyDrFjYv2c322zzCMsgpVttjUz9lWDrBoUg",
  authDomain: "cosmic-compass-5fd5e.firebaseapp.com",
  databaseURL: "https://cosmic-compass-5fd5e-default-rtdb.europe-west1.firebasedatabase.app",
  projectId: "cosmic-compass-5fd5e",
  storageBucket: "cosmic-compass-5fd5e.firebasestorage.app",
  messagingSenderId: "160679439170",
  appId: "1:160679439170:web:bafbb80eb30f64ee9476db"
};

// Initialize Firebase App and Database
// Explicitly passing databaseURL to getDatabase is best practice for modular SDK
const firebaseAppInstance = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();
const db = getDatabase(firebaseAppInstance, firebaseConfig.databaseURL);

// --- Utilities ---

const getUserId = () => {
  let id = localStorage.getItem('cosmic_user_id');
  if (!id) {
    id = 'user_' + Math.random().toString(36).substring(2, 11) + Date.now();
    localStorage.setItem('cosmic_user_id', id);
  }
  return id;
};

const saveToLocal = (state: AppState) => {
  try { localStorage.setItem(MASTER_STORAGE_KEY, JSON.stringify(state)); } catch (e) { console.error(e); }
};

const loadFromLocal = (defaults: AppState): AppState => {
  try {
    const data = localStorage.getItem(MASTER_STORAGE_KEY);
    return data ? JSON.parse(data) : defaults;
  } catch { return defaults; }
};

const syncToCloud = async (uid: string, data: AppState) => {
  try {
    await set(ref(db, `users/${uid}`), { ...data, lastSynced: new Date().toISOString() });
    return true;
  } catch (e) { console.error("Sync Error:", e); return false; }
};

const loadFromCloud = async (uid: string): Promise<AppState | null> => {
  try {
    const snap = await get(ref(db, `users/${uid}`));
    return snap.exists() ? snap.val() as AppState : null;
  } catch (e) { console.error("Load Error:", e); return null; }
};

