  birthDetails: { name: 'Harshkumar Patel', dob: '1995-01-17', tob: '15:58', pob: 'Vadodara, India' },
  lifeEvents: [
    { date: '2021-08-24', description: 'Health crisis: Platelets dropped to 10k' },
    { date: '2022-01-04', description: 'Married Pankti Patel' },
    { date: '2024-11-06', description: 'Moved to Germany' }
  ],
  outputLanguage: 'Gujarati',
  enableGoogleSearch: false,
  chatHistory: [],
  lastReading: ''
};

const App: React.FC = () => {
  const userId = getUserId();
  const [activeTab, setActiveTab] = useState<'chart' | 'oracle'>('chart');
  const [isLoading, setIsLoading] = useState(false);
  const [isCloudSynced, setIsCloudSynced] = useState(false);
  const [appState, setAppState] = useState<AppState>(() => loadFromLocal(DEFAULT_STATE));

  const chatSessionRef = useRef<Chat | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadFromCloud(userId).then(cloudData => {
      if (cloudData) {
        setAppState(prev => ({ ...prev, ...cloudData }));
        setIsCloudSynced(true);
      }
    });
  }, [userId]);

  useEffect(() => {
    saveToLocal(appState);
    const timer = setTimeout(() => {
      syncToCloud(userId, appState).then(setIsCloudSynced);
