    setIsLoading(true);
    try {
      // Use process.env.API_KEY directly in the named parameter.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = createPromptContext(appState) + "\n\nProvide a comprehensive esoteric life analysis based on the current stars and the user's timeline.";

