    const newChatHistory: ChatMessage[] = [...appState.chatHistory, { role: 'user', text: msg }];
    setAppState(prev => ({ ...prev, chatHistory: newChatHistory }));
    setIsLoading(true);

    try {
      // Create fresh instance of GoogleGenAI for each interaction.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      if (!chatSessionRef.current) {
        chatSessionRef.current = ai.chats.create({
          model: LATEST_FLASH_MODEL,
          config: { 
            systemInstruction: createPromptContext(appState),
            tools: appState.enableGoogleSearch ? [{ googleSearch: {} }] : undefined
          }
        });
      }

      const response = await chatSessionRef.current.sendMessage({ message: msg });
      // Extract generated text from .text property.
      setAppState(prev => ({
        ...prev,
        chatHistory: [...newChatHistory, { role: 'model', text: response.text || "" }]
      }));
