             <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">
               {isCloudSynced ? 'Spirit Logged' : 'Syncing Destiny...'}
             </span>
          </div>
          <select 
            value={appState.outputLanguage} 
            onChange={e => setAppState(prev => ({...prev, outputLanguage: e.target.value}))}
            className="bg-transparent border border-white/10 rounded-full px-3 py-1 text-[10px] font-black uppercase text-indigo-400 focus:outline-none"
          >
            <option value="English">English</option>
            <option value="Gujarati">Gujarati</option>
            <option value="Hindi">Hindi</option>
          </select>
        </div>
      </header>

