          <button 
            onClick={() => setActiveTab('oracle')} 
            className={`px-8 py-3 rounded-xl font-bold transition-all ${activeTab === 'oracle' ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
