                className="mt-6 w-full py-3 rounded-xl border border-dashed border-white/20 text-[11px] font-black uppercase text-gray-400 hover:text-white hover:border-white/40 transition-all"
              >
                + Append Memory
              </button>
            </section>
          </div>

          <div className="lg:col-span-4 flex flex-col h-full">
            <button 
              onClick={handleGenerateReading} 
              disabled={isLoading}
              className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 py-6 rounded-3xl font-black uppercase tracking-widest text-white shadow-2xl hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-50"
            >
              {isLoading ? "Consulting..." : "Generate Reading"}
            </button>

            {appState.lastReading && (
              <div className="mt-6 glass rounded-3xl p-6 flex-1 overflow-y-auto max-h-[500px] custom-scrollbar shadow-2xl">
                <div className="text-sm text-gray-200 leading-relaxed whitespace-pre-wrap font-medium">
                  {appState.lastReading}
                </div>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="max-w-3xl mx-auto glass rounded-3xl overflow-hidden h-[70vh] flex flex-col shadow-2xl">
          <div className="px-6 py-4 bg-white/5 border-b border-white/10 flex justify-between items-center">
