const App: React.FC = () => {
  const [userId] = useState(() => {
    let id = localStorage.getItem('cosmic_user_id');
    if (!id) {
      id = 'user_' + Math.random().toString(36).substring(2, 11);
      localStorage.setItem('cosmic_user_id', id);
    }
    return id;
  });

  const [appState, setAppState] = useState<AppState>(() => {
    try {
      const local = localStorage.getItem(MASTER_STORAGE_KEY);
      return local ? JSON.parse(local) : DEFAULT_STATE;
    } catch { return DEFAULT_STATE; }
  });

  const [loading, setLoading] = useState(false);
  const [reading, setReading] = useState('');
  const [isKeyModalOpen, setIsKeyModalOpen] = useState(false);
  const [activeKey, setActiveKey] = useState(() => localStorage.getItem(API_KEY_STORAGE_KEY) || '');
  const [syncing, setSyncing] = useState(false);

  const chatSessionRef = useRef<Chat | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Cloud Sync Logic
  useEffect(() => {
    const initCloud = async () => {
      try {
        const snap = await get(ref(db, `users/${userId}`));
        if (snap.exists()) setAppState(prev => ({ ...prev, ...snap.val() }));
      } catch (e) { console.error("Cloud Error:", e); }
    };
    initCloud();
  }, [userId]);

  useEffect(() => {
    localStorage.setItem(MASTER_STORAGE_KEY, JSON.stringify(appState));
    const timer = setTimeout(async () => {
      setSyncing(true);
      try {
        await set(ref(db, `users/${userId}`), { ...appState, lastUpdated: new Date().toISOString() });
      } catch (err) {
        console.error("Cloud sync failed:", err);
      } finally { setSyncing(false); }
