    if (!(await ensureKey())) return;
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: getCurrentKey() });
      const res = await ai.models.generateContent({
        model: LATEST_PRO_MODEL,
        contents: buildPrompt(),
        config: { tools: appState.enableGoogleSearch ? [{ googleSearch: {} }] : undefined },
      });
      setReading(res.text || 'The stars are silent.');
    } catch (e: any) {
      console.error(e);
      if (e.message?.includes("403") || e.message?.includes("PERMISSION_DENIED")) {
        alert("API Key rejection. Check billing or restrictions.");
        setIsKeyModalOpen(true);
      } else { alert("Cosmic error: " + (e.message || "Unknown issue")); }
    } finally { setLoading(false); }
  };

  const handleSendMessage = async (text: string) => {
    if (!text.trim() || !(await ensureKey())) return;
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: getCurrentKey() });
      if (!chatSessionRef.current) {
        chatSessionRef.current = ai.chats.create({
          model: LATEST_FLASH_MODEL,
          config: { systemInstruction: buildPrompt(true) }
        });
      }
      const newHist: ChatMessage[] = [...appState.chatHistory, { role: 'user', text }];
      setAppState(prev => ({ ...prev, chatHistory: newHist }));
      const result = await chatSessionRef.current.sendMessage({ message: text });
      setAppState(prev => ({ ...prev, chatHistory: [...newHist, { role: 'model', text: result.text || '' }] }));
    } catch (e: any) {
      if (e.message?.includes("403")) setIsKeyModalOpen(true);
      alert("Oracle Interrupted: " + (e.message || "Retry later"));
    } finally { setLoading(false); }
  };

