            {syncing ? 'Syncing...' : 'Cloud Connected'}
          </div>
          <button 
            onClick={() => setIsKeyModalOpen(true)} 
            className={`px-4 py-1.5 rounded-full border text-[10px] font-black uppercase tracking-widest transition-all ${activeKey ? 'bg-indigo-600/20 border-indigo-500/30 text-indigo-300' : 'bg-red-500/20 border-red-500/30 text-red-300 animate-pulse'}`}
          >
