          </button>
          <select value={appState.outputLanguage} onChange={e => setAppState(p => ({...p, outputLanguage: e.target.value}))} className="bg-white/5 border border-white/10 rounded-full px-4 py-1.5 text-[10px] font-bold text-indigo-300 uppercase tracking-widest outline-none cursor-pointer">
            <option value="English">English</option>
            <option value="Gujarati">Gujarati</option>
          </select>
        </div>
      </header>

      <div className="flex justify-center mb-12">
        <div className="glass p-1.5 rounded-2xl flex space-x-2 shadow-2xl">
          <button onClick={() => setAppState(p => ({...p, isChatMode: false}))} className={`px-10 py-3 rounded-xl font-bold transition-all ${!appState.isChatMode ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Profile Mandali</button>
          <button onClick={() => setAppState(p => ({...p, isChatMode: true}))} className={`px-10 py-3 rounded-xl font-bold transition-all ${appState.isChatMode ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Oracle Chat</button>
        </div>
      </div>

      {!appState.isChatMode ? (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-500">
          <div className="lg:col-span-4 space-y-6">
            <section className="glass rounded-[2rem] p-8 glow-border shadow-xl">
              <h2 className="font-serif text-2xl text-white mb-8">Birth Data</h2>
              <InputField label="Name" type="text" value={appState.birthDetails.name} onChange={v => setAppState(p => ({...p, birthDetails: {...p.birthDetails, name: v}}))} />
              <div className="grid grid-cols-2 gap-4">
                <InputField label="Date" type="date" value={appState.birthDetails.dob} onChange={v => setAppState(p => ({...p, birthDetails: {...p.birthDetails, dob: v}}))} />
                <InputField label="Time" type="time" value={appState.birthDetails.tob} onChange={v => setAppState(p => ({...p, birthDetails: {...p.birthDetails, tob: v}}))} />
